DG.put("ath-pakhyaan-charitr-likhyate/297",{"n":297,"title":null,"title_roman":null,"page":2195,"blocks":[{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2195,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":2195,"lines":[{"gurmukhi":"ਬਿਜੈ ਸੂਰ ਖਤ੍ਰੀ ਇਕ ਰਹੈ। ਸਿਧ ਪਾਲ ਤਾ ਕਹ ਜਗ ਕਹੈ।","roman":"Bijai soor khatree ik rahai | sidh paal taa kah jag kahai |","meaning_en":"There lived a Khatri, Vijay Sur, whom the world called Sidh Pal.","page":2195,"meaning_status":"draft","note":"ਬਿਜੈ ਸੂਰ: read as a name, Vijay Sur; uncertain whether Sidh Pal is another name of the same man (so taken)."},{"gurmukhi":"ਸਮਸਦੀਨ ਦਿਲੀਸ ਦਿਵਾਨਾ। ਜਾਨਤ ਸਕਲ ਰਾਵ ਅਰੁ ਰਾਨਾ। ੧।","roman":"Samasdeen dilees divaanaa | jaanat sakal raav aru raanaa | 1 |","meaning_en":"Shamsuddin, the mad lord of Delhi, was known to all kings and ranas.","page":2195,"meaning_status":"draft","note":"ਦਿਵਾਨਾ 'mad/crazed' as printed."}]},{"type":"verse","number":[2],"number_text":"੨।","page":2195,"lines":[{"gurmukhi":"ਲਛਿਮਨ ਸੈਨ ਧਾਮ ਸੁਤ ਸੁਭ ਮਤਿ। ਬਜ੍ਰ ਸੈਨ ਦੂਸਰੋ ਬਿਕਟ ਮਤਿ।","roman":"Lachhiman sain dhaam sut subh mati | bajr sain doosro bikat mati |","meaning_en":"He had a son Lachhman Sen in the house, of good mind, and a second, Bajra Sen, of fierce mind.","page":2195,"meaning_status":"draft"},{"gurmukhi":"ਸਕੁਚ ਮਤੀ ਦੁਹਿਤਾ ਇਕ ਤਾ ਕੇ। ਨਰੀ ਨਾਗਨੀ ਸਮ ਨਹਿ ਜਾ ਕੇ। ੨।","roman":"Sakuch matee duhitaa ik taa ke | naree naagnee sam nahi jaa ke | 2 |","meaning_en":"He had a daughter, Sakuch Mati, whom no woman or serpent-woman equalled.","page":2195,"meaning_status":"draft","note":"ਸਕੁਚ ਮਤੀ: name transliterated as printed."}]},{"type":"verse","number":[3],"number_text":"੩।","page":2195,"lines":[{"gurmukhi":"ਸਮਸਦੀਨ ਦਿਲੀਸ ਜੁਵਾਨਾ। ਮਾਨਤ ਆਨਿ ਦੇਸ ਜਿਹ ਨਾਨਾ।","roman":"Samasdeen dilees juvaanaa | maanat aani des jih naanaa |","meaning_en":"Shamsuddin, the young lord of Delhi, whom many other countries obeyed,","page":2195,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਦਿਵਸ ਵਹੁ ਗਯੋ ਸਿਕਾਰਾ। ਜਾ ਦਿਸ ਹੁਤੀ ਕੇਹਰੀ ਬਾਰਾ। ੩।","roman":"Ek divas vahu gayo sikaaraa | jaa dis hutee kehree baaraa | 3 |","meaning_en":"one day went hunting, in the direction where there was a lion's den.","page":2195,"meaning_status":"draft","note":"ਕੇਹਰੀ ਬਾਰਾ read as 'lion's lair'; uncertain."}]},{"type":"verse","number":[4],"number_text":"੪।","page":2195,"lines":[{"gurmukhi":"ਤਹੀ ਦਿਲੀਸ ਆਪੁ ਚਲਿ ਗਯੋ। ਜਹਾ ਸਿੰਘਨੀ ਚਿਤਵਤ ਭਯੋ।","roman":"Tahee dilees aapu chali gayo | jahaa singhnee chitvat bhayo |","meaning_en":"The lord of Delhi went there himself, where he sighted a lioness.","page":2195,"meaning_status":"draft"},{"gurmukhi":"ਸਿਧ ਪਾਲ ਲੀਏ ਅਪਨੇ ਸੰਗਾ। ਔਰ ਲੀਏ ਅਨਗਨ ਚਤੁਰੰਗਾ। ੪।","roman":"Sidh paal lee'e apne sangaa | aur lee'e angan chaturangaa | 4 |","meaning_en":"He took Sidh Pal with him, and took countless fourfold troops besides.","page":2195,"meaning_status":"draft"}]},{"type":"verse","number":[5],"number_text":"੫।","page":2195,"lines":[{"gurmukhi":"ਤਾ ਪਰ ਕਰੀ ਝੁਕਾਵਤ ਭਯੋ। ਕੇਹਰਿ ਸਮੈ ਜਨਮ ਤਬ ਲਯੋ।","roman":"Taa par karee jhukaavat bhayo | kehri samai janam tab layo |","meaning_en":"He urged his elephant at her; at that time the lion gave birth;","page":2195,"meaning_status":"draft","note":"uncertain; read as the lioness giving birth as she was attacked."},{"gurmukhi":"ਅਰਧ ਰਹਾਤਨ ਮਾਤ ਕੁਖੂਤਰ। ਅਰਧਹ ਨਾਕਰ ਗਜ ਮਸਤਕ ਪਰ। ੫।","roman":"Aradh rahaatan maat kukhootar | ardhah naakar gaj mastak par | 5 |","meaning_en":"half (the cub) remained in the mother's womb, and half was upon the elephant's forehead.","page":2195,"meaning_status":"draft","note":"uncertain: ਕੁਖੂਤਰ, ਨਾਕਰ; read as 'womb' and 'upon'."}]},{"type":"verse","number":[6],"number_text":"੬।","page":2195,"lines":[{"gurmukhi":"ਤਹ ਇਕ ਭਾਟ ਕੌਤਕ ਅਸ ਲਹਾ। ਹਜਰਤਿ ਸੁਨਤ ਦੋਹਰਾ ਕਹਾ।","roman":"Tah ik bhaat kautak as lahaa | hajarti sunat dohraa kahaa |","meaning_en":"A bard there saw such a wonder, and recited a doha in the Hazrat's hearing,","page":2195,"meaning_status":"draft","note":"ਹਜਰਤਿ: 'the Hazrat', i.e. the emperor."},{"gurmukhi":"ਸੁ ਮੈ ਕਹਤ ਹੋ ਸੁਨਹੁ ਪ੍ਯਾਰੇ। ਜੋ ਤਿਨ ਸਾਹ ਨ ਚਿਤ ਤੇ ਟਾਰੇ।੬।","roman":"Su mai kahat ho sunhu pyaare | jo tin saah na chit te taare | 6 |","meaning_en":"which I tell you, listen dear, which the Shah did not remove from his mind.","page":2195,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2195,"meaning_status":"draft"},{"type":"verse","number":[7],"number_text":"੭।","page":2195,"lines":[{"gurmukhi":"ਸਿੰਘ ਸਾਪੁਰਸ ਪਦਮਿਨੀ ਇਨ ਕਾ ਇਹੈ ਸੁਭਾਉ।","roman":"Singh saapuras padminee in kaa ihai subhaau |","meaning_en":"Lion, noble man and padmini woman: this is their nature;","page":2195,"meaning_status":"draft","note":"padmini: the best type of woman in the Koka classification."},{"gurmukhi":"ਜ੍ਯੋ ਜ੍ਯੋ ਦੁਖ ਗਾੜੋ ਪਰੈ ਤ੍ਯੋ ਤ੍ਯੋ ਆਗੇ ਪਾਉ। ੭।","roman":"Jyo jyo dukh gaaro parai tyo tyo aage paau | 7 |","meaning_en":"the more heavy trouble falls on them, the more they step forward.","page":2195,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2195,"meaning_status":"draft"},{"type":"verse","number":[8],"number_text":"੮।","page":2195,"lines":[{"gurmukhi":"ਭਾਟ ਜਬੈ ਇਹ ਭਾਤਿ ਉਚਾਰਾ। ਹਜਰਤਿ ਬਚਨ ਸ੍ਰਵਨ ਇਹ ਧਾਰਾ।","roman":"Bhaat jabai ih bhaati uchaaraa | hajarti bachan sravan ih dhaaraa |","meaning_en":"When the bard spoke in this way, the Hazrat took the words into his ears.","page":2195,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਅਪਨੇ ਮਹਲਨ ਮਹਿ ਆਯੋ। ਸਿਧ ਪਾਲ ਕਹ ਬੋਲ ਪਠਾਯੋ। ੮।","roman":"Jab apne mahlan mahi aayo | sidh paal kah bol pathaayo | 8 |","meaning_en":"When he came to his palaces, he sent word to call Sidh Pal.","page":2195,"meaning_status":"draft"}]},{"type":"verse","number":[9],"number_text":"੯।","page":2197,"lines":[{"gurmukhi":"ਤਾ ਸੋ ਇਹ ਬਿਧਿ ਨਾਥ ਬਖਾਨਾ। ਤੈ ਹੈ ਮੋਰ ਵਜੀਰ ਸ੍ਯਾਨਾ।","roman":"Taa so ih bidhi naath bakhaanaa | tai hai mor vajeer syaanaa |","meaning_en":"He said to him thus: 'You are my wise minister.","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਅਬ ਕਛੁ ਅਸ ਤੁਮ ਕਰਹੁ ਉਪਾਈ। ਜਾ ਤੇ ਮਿਲੈ ਪਦੁਮਿਨਿ ਆਈ। ੯।","roman":"Ab kachhu as tum karhu upaaee | jaa te milai padumini aaee | 9 |","meaning_en":"Now devise some means by which a padmini may come and meet me.'","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":2197,"lines":[{"gurmukhi":"ਸਿਧ ਪਾਲ ਇਹ ਭਾਤਿ ਉਚਾਰਾ। ਸੁਨ ਹਜਰਤਿ ਜੂ ਬਚਨ ਹਮਾਰਾ।","roman":"Sidh paal ih bhaati uchaaraa | sun hajarti joo bachan hamaaraa |","meaning_en":"Sidh Pal spoke thus: 'Listen to my word, Hazrat:","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਅਪਨੀ ਤੁਮ ਸੈਨ ਬੁਲਾਵੋ। ਮੋਹਿ ਸਿੰਗਲਾਦੀਪ ਪਠਾਵੋ। ੧੦।","roman":"Sabh apnee tum sain bulaavo | mohi singlaadeep pathaavo | 10 |","meaning_en":"call all your army, and send me to Singaladip (Sri Lanka).","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[11],"number_text":"੧੧।","page":2197,"lines":[{"gurmukhi":"ਜੌ ਤੁਮਰੀ ਆਗ੍ਯਾ ਕਹ ਪਾਊ। ਅਮਿਤ ਸੈਨ ਲੈ ਤਹਾ ਸਿਧਾਊ।","roman":"Jau tumree aagyaa kah paaoo | amit sain lai tahaa sidhaaoo |","meaning_en":"If I receive your order, I will go there with a boundless army;","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਖੜਗ ਸਿੰਗਲਾਦੀਪ ਮਚੈਹੋ। ਜ੍ਯੋ ਤ੍ਯੋ ਕੈ ਪਦੁਮਿਨਿ ਲੈ ਐਹੋ। ੧੧।","roman":"Kharag singlaadeep machaiho | jyo tyo kai padumini lai aiho | 11 |","meaning_en":"I will raise the sword in Singaladip, and somehow bring a padmini.'","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":2197,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਗਯੋ ਧਾਮ ਜਬ ਰਾਜਾ। ਬਾਜਤ ਭਾਤ ਅਨੇਕਨ ਬਾਜਾ।","roman":"Yau kahi gayo dhaam jab raajaa | baajat bhaat anekan baajaa |","meaning_en":"Saying this he went to his house, with instruments of many kinds sounding.","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਬੈਰੀ ਹੁਤੋ ਤਹਾ ਇਕ ਤਾ ਕੋ। ਭੇਦ ਕਹਾ ਹਜਰਤਿ ਪੈ ਵਾ ਕੋ। ੧੨।","roman":"Bairee huto tahaa ik taa ko | bhed kahaa hajarti pai vaa ko | 12 |","meaning_en":"He had an enemy there, who told the Hazrat the secret about him:","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":2197,"lines":[{"gurmukhi":"ਏਕ ਧਾਮ ਦੁਹਿਤਾ ਹੈ ਯਾ ਕੇ। ਪਰੀ ਪਦਮਿਨਿ ਤੁਲਿ ਨ ਤਾ ਕੇ।","roman":"Ek dhaam duhitaa hai yaa ke | paree padmini tuli na taa ke |","meaning_en":"'He has a daughter in his house; no fairy or padmini is equal to her.","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਪਠੈ ਮਨੁਛ ਤਿਹ ਹੇਰਿ ਮੰਗਾਵਹੁ। ਤਿਹ ਪਾਛੇ ਪਦੁਮਿਨਿ ਖੁਜਾਵਹੁ। ੧੩।","roman":"Pathai manuchh tih heri mangaavhu | tih paachhe padumini khujaavhu | 13 |","meaning_en":"Send a man to see her and have her fetched; afterwards search for the padmini.'","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":2197,"lines":[{"gurmukhi":"ਹਜਰਤਿ ਸੁਨਤ ਜਬੈ ਸੇ ਭਯੋ। ਤਤ ਛਿਨ ਦੂਤੀ ਤਹਾ ਪਠਯੋ।","roman":"Hajarti sunat jabai se bhayo | tat chhin dootee tahaa pathyo |","meaning_en":"When the Hazrat heard this, at that moment he sent a go-between there,","page":2197,"meaning_status":"draft","note":"ਸੇ ਭਯੋ: 'heard so'; read loosely; uncertain."},{"gurmukhi":"ਚਤੁਰਿ ਚਿਤੇਰੀ ਰੂਪ ਉਜਿਯਾਰੀ। ਬਿਸੁਕਰਮਾ ਕੀ ਜਾਨ ਕੁਮਾਰੀ। ੧੪।","roman":"Chaturi chiteree roop ujiyaaree | bisukarmaa kee jaan kumaaree | 14 |","meaning_en":"a clever woman painter of radiant beauty, known as Vishvakarma's daughter.","page":2197,"meaning_status":"draft","note":"Vishvakarma: the divine craftsman."}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":2197,"lines":[{"gurmukhi":"ਇਕ ਚਤੁਰਾ ਅਰੁ ਦੁਤਿਯ ਚਿਤੇਰੀ। ਪ੍ਰਤਿਮਾ ਦੁਤਿਯ ਮਦਨ ਜਨ ਕੇਰੀ।","roman":"Ik chaturaa aru dutiy chiteree | pratimaa dutiy madan jan keree |","meaning_en":"She was clever, and a painter; an image of a second Madan.","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਗੋਰ ਬਰਨ ਅਰੁ ਖਾਏ ਪਾਨਾ। ਜਾਨੁਕ ਚੜਾ ਚੰਦ ਅਸਮਾਨਾ। ੧੫।","roman":"Gor baran aru khaae paanaa | jaanuk charaa chand asmaanaa | 15 |","meaning_en":"Fair of colour, chewing betel, as if the moon had risen in the sky.","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[16],"number_text":"੧੬।","page":2197,"lines":[{"gurmukhi":"ਤਾ ਕੇ ਧਾਮ ਚਿਤੇਰਨਿ ਗਈ। ਲਿਖਿ ਲ੍ਯਾਵਤ ਪ੍ਰਤਿਮਾ ਤਿਹ ਭਈ।","roman":"Taa ke dhaam chiterni gaee | likhi lyaavat pratimaa tih bhaee |","meaning_en":"The painter woman went to Sidh Pal's house, drew a picture and brought it.","page":2197,"meaning_status":"draft","note":"ਤਾ ਕੇ ਧਾਮ read as Sidh Pal's house (the daughter's)."},{"gurmukhi":"ਜਬ ਲੈ ਕਰਿ ਕਰ ਸਾਹ ਨਿਹਾਰੀ। ਜਾਨੁਕ ਤਾਨਿ ਕਟਾਰੀ ਮਾਰੀ। ੧੬।","roman":"Jab lai kari kar saah nihaaree | jaanuk taani kataaree maaree | 16 |","meaning_en":"When the Shah took it in hand and looked, it was as if a dagger had been drawn and struck him.","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":2197,"lines":[{"gurmukhi":"ਸਭ ਸੁਧਿ ਗਈ ਮਤ ਹ੍ਵੈ ਝੂੰਮਾ। ਘਾਇ ਲਗੇ ਘਾਯਲ ਜਨੁ ਘੂੰਮਾ।","roman":"Sabh sudhi gaee mat hvai jhoonmaa | ghaai lage ghaayal janu ghoonmaa |","meaning_en":"All his senses went; he reeled as if drunk, like a wounded man wandering about.","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਤਨ ਕੀ ਰਹੀ ਨ ਤਨਿਕ ਸੰਭਾਰਾ। ਜਨੁ ਡਸਿ ਗਯੋ ਨਾਗ ਕੌਡਿਯਾਰਾ। ੧੭।","roman":"Tan kee rahee na tanik sanbhaaraa | janu dasi gayo naag kaudiyaaraa | 17 |","meaning_en":"He had no care for his body, as if a hooded cobra had bitten him.","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":2197,"lines":[{"gurmukhi":"ਇਕ ਦਿਨ ਕਰੀ ਸਾਹ ਮਿਜਮਾਨੀ। ਸਭ ਪੁਰ ਨਾਰਿ ਧਾਮ ਮਹਿ ਆਨੀ।","roman":"Ik din karee saah mijmaanee | sabh pur naari dhaam mahi aanee |","meaning_en":"One day the Shah gave a feast, and had all the women of the city brought into his house.","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਸਿਧ ਪਾਲ ਕੀ ਸੁਤਾ ਜਬਾਈ। ਸਕਲ ਦੀਪ ਜ੍ਯੋ ਸਭਾ ਸੁਹਾਈ। ੧੮।","roman":"Sidh paal kee sutaa jabaaee | sakal deep jyo sabhaa suhaaee | 18 |","meaning_en":"Sidh Pal's daughter came, and the assembly shone like all the continents.","page":2197,"meaning_status":"draft","note":"uncertain."}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":2197,"lines":[{"gurmukhi":"ਛਿਦ੍ਰ ਬੀਚ ਕਰਿ ਤਾਹਿ ਨਿਹਾਰਾ। ਹਜਰਤਿ ਭਯੋ ਤਬੈ ਮਤਵਾਰਾ।","roman":"Chhidr beech kari taahi nihaaraa | hajarti bhayo tabai matvaaraa |","meaning_en":"He looked at her through a hole; then the Hazrat became drunk with passion.","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਮਨ ਤਰੁਨੀ ਕੇ ਰੂਪ ਬਿਕਾਨ੍ਯੋ। ਮ੍ਰਿਤਕ ਸੋ ਤਨੁ ਰਹਿਯੋ ਪਛਾਨ੍ਯੋ। ੧੯।","roman":"Man tarunee ke roop bikaanyo | mritak so tanu rahiyo pachhaanyo | 19 |","meaning_en":"His mind was sold to the young woman's form; his body remained like a corpse.","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":2197,"lines":[{"gurmukhi":"ਹਜਰਤਿ ਸਕਲ ਪਠਾਨ ਬੁਲਾਏ। ਸਿਧ ਪਾਲ ਕੈ ਧਾਮ ਪਠਾਏ।","roman":"Hajarti sakal pathaan bulaae | sidh paal kai dhaam pathaae |","meaning_en":"The Hazrat called all the Pathans and sent them to Sidh Pal's house:","page":2197,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਅਪਨੀ ਦੁਹਿਤਾ ਮੁਹਿ ਦੀਜੈ। ਨਾਤਰ ਮੀਚ ਮੂੰਡ ਪਰ ਲੀਜੈ। ੨੦।","roman":"Kai apnee duhitaa muhi deejai | naatar meech moond par leejai | 20 |","meaning_en":"'Either give me your daughter, or take death on your head.'","page":2197,"meaning_status":"draft"}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":2199,"lines":[{"gurmukhi":"ਸਕਲ ਪਠਾਨ ਤਵਨ ਕੇ ਗਏ। ਹਜਰਤਿ ਕਹੀ ਸੁ ਭਾਖਤ ਭਏ।","roman":"Sakal pathaan tavan ke gae | hajarti kahee su bhaakhat bhae |","meaning_en":"All the Pathans went to him and said what the Hazrat had said:","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਸਿਧ ਪਾਲ ਧੰਨ ਭਾਗ ਤਿਹਾਰੇ। ਗ੍ਰਿਹ ਆਵਹਿਗੇ ਸਾਹ ਸਵਾਰੇ। ੨੧।","roman":"Sidh paal dhann bhaag tihaare | grih aavhige saah savaare | 21 |","meaning_en":"'Sidh Pal, blessed is your fortune; the Shah will come adorned to your house.'","page":2199,"meaning_status":"draft"}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":2199,"lines":[{"gurmukhi":"ਸਿਧ ਪਾਲ ਐਸੋ ਜਬ ਸੁਨਾ। ਅਧਿਕ ਦੁਖਿਤ ਹ੍ਵੈ ਮਸਤਕ ਧੁਨਾ।","roman":"Sidh paal aiso jab sunaa | adhik dukhit hvai mastak dhunaa |","meaning_en":"When Sidh Pal heard this, he was greatly grieved and struck his forehead:","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਦੈਵ ਕਵਨ ਗਤਿ ਕਰੀ ਹਮਾਰੀ। ਗ੍ਰਿਹ ਅਸਿ ਉਪਜੀ ਸੁਤਾ ਦੁਖਾਰੀ। ੨੨।","roman":"Daiv kavan gati karee hamaaree | grih asi upjee sutaa dukhaaree | 22 |","meaning_en":"'What state has Fate brought on us; such a sorrowful daughter has been born in my house.","page":2199,"meaning_status":"draft"}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":2199,"lines":[{"gurmukhi":"ਜੌ ਨਹਿ ਦੇਤ ਤੁ ਬਿਗਰਤ ਕਾਜਾ। ਜਾਤ ਦਏ ਛਤ੍ਰਿਨ ਕੀ ਲਾਜਾ।","roman":"Jau nahi det tu bigrat kaajaa | jaat dae chhatrin kee laajaa |","meaning_en":"If I do not give her, the matter is spoiled; if I give her, the honour of the Kshatriyas goes.","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਮੁਗਲ ਪਠਾਨ ਤੁਰਕ ਘਰ ਮਾਹੀ। ਅਬ ਲਗਿ ਗੀ ਛਤ੍ਰਾਨੀ ਨਾਹੀ। ੨੩।","roman":"Mugal pathaan turak ghar maahee | ab lagi gee chhatraanee naahee | 23 |","meaning_en":"There are Mughals, Pathans and Turks in the house; up to now no Kshatriya woman has gone (to them).","page":2199,"meaning_status":"draft","note":"as printed; 'in the house' (ਘਰ ਮਾਹੀ) uncertain."}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":2199,"lines":[{"gurmukhi":"ਛਤ੍ਰਿਨ ਕੇ ਅਬ ਲਗੇ ਨ ਭਈ। ਦੁਹਿਤਾ ਕਾਢਿ ਤੁਰਕ ਕਹ ਦਈ।","roman":"Chhatrin ke ab lage na bhaee | duhitaa kaadhi turak kah daee |","meaning_en":"Among the Kshatriyas, up to now it has not happened that a daughter was taken out and given to a Turk.","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਰਜਪੂਤਨ ਕੇ ਹੋਤਹ ਆਈ। ਪੁਤ੍ਰੀ ਧਾਮ ਮਲੇਛ ਪਠਾਈ। ੨੪।","roman":"Rajpootan ke hotah aaee | putree dhaam malechh pathaaee | 24 |","meaning_en":"Has it come to pass among Rajputs that a daughter is sent to a mlechha's house?","page":2199,"meaning_status":"draft","note":"printed without question mark; read so; uncertain."}]},{"type":"verse","number":[25],"number_text":"੨੫।","page":2199,"lines":[{"gurmukhi":"ਹਾਡਨ ਏਕ ਦੂਸਰਨ ਖਤ੍ਰੀ। ਤੁਰਕਨ ਕਹ ਇਨ ਦਈ ਨ ਪੁਤ੍ਰੀ।","roman":"Haadan ek doosran khatree | turkan kah in daee na putree |","meaning_en":"The Hadas, another Khatri clan, have not given a daughter to the Turks.","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਛਤ੍ਰੀ ਅਸ ਕਰਮ ਕਮਾਵੈ। ਕੁੰਭੀ ਨਰਕ ਦੇਹ ਜੁਤ ਜਾਵੈ। ੨੫।","roman":"Jo chhatree as karam kamaavai | kunbhee narak deh jut jaavai | 25 |","meaning_en":"The Kshatriya who does such a deed goes with his body to the Kumbhi hell.","page":2199,"meaning_status":"draft","note":"Kumbhi: hell of the cooking pot."}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":2199,"lines":[{"gurmukhi":"ਜੋ ਨਰ ਤੁਰਕਹਿ ਦੇਤ ਦੁਲਾਰੀ। ਧ੍ਰਿਗ ਧ੍ਰਿਗ ਜਗ ਤਿਹ ਕਰਤ ਉਚਾਰੀ।","roman":"Jo nar turakhi det dulaaree | dhrig dhrig jag tih karat uchaaree |","meaning_en":"The man who gives his dear daughter to a Turk, the world says 'shame, shame' of him.","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਲੋਕ ਪ੍ਰਲੋਕ ਤਾਹਿ ਕੋ ਜੈਹੈ। ਛਤ੍ਰੀ ਸੁਤਾ ਤੁਰਕ ਕਹ ਦੈਹੈ। ੨੬।","roman":"Lok pralok taahi ko jaihai | chhatree sutaa turak kah daihai | 26 |","meaning_en":"He loses both this world and the next, who gives a Kshatriya's daughter to a Turk.","page":2199,"meaning_status":"draft"}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":2199,"lines":[{"gurmukhi":"ਹਾਡਿਯਨ ਸੁਤਾ ਤੁਰਕਿ ਨਹਿ ਦਈ। ਛਤ੍ਰਾਨੀ ਤੁਰਕਨੀ ਨ ਭਈ।","roman":"Haadiyan sutaa turki nahi daee | chhatraanee turaknee na bhaee |","meaning_en":"The Hadas did not give a daughter to a Turk; no Kshatriya woman became a Turkish woman.","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਕਛ ਰਜਪੂਤਨ ਲਾਜ ਗਵਾਈ। ਰਾਨੀ ਤੇ ਬੇਗਮਾ ਕਹਾਈ। ੨੭।","roman":"Kachh rajpootan laaj gavaaee | raanee te begmaa kahaaee | 27 |","meaning_en":"Some Rajputs have lost their honour, and queens have come to be called begums.","page":2199,"meaning_status":"draft"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":2199,"lines":[{"gurmukhi":"ਅਬ ਮੈ ਧਰੈ ਇਹੌ ਨਿਜੁ ਬੁਧਾ। ਮੰਡੌ ਬੀਰ ਖੇਤ ਮਹਿ ਕ੍ਰੁਧਾ।","roman":"Ab mai dharai ihau niju budhaa | mandau beer khet mahi krudhaa |","meaning_en":"Now I will take up my own wisdom, and stand in the field as an angry warrior,","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਪਹਿਰਿ ਕੌਚ ਕਰਿ ਖੜਗ ਸੰਭਾਰੌ। ਚੁਨਿ ਚੁਨਿ ਆਜੁ ਪਖਰਿਯਾ ਮਾਰੌ। ੨੮।","roman":"Pahiri kauch kari kharag sanbhaarau | chuni chuni aaju pakhriyaa maarau | 28 |","meaning_en":"wearing armour and gripping my sword; I will pick out and kill the armoured men today.'","page":2199,"meaning_status":"draft"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":2199,"lines":[{"gurmukhi":"ਤਬ ਕੰਨ੍ਯਾ ਨਿਜੁ ਪਿਤਾ ਹਕਾਰਾ। ਇਹ ਬਿਧਿ ਤਾ ਸੌ ਮੰਤ੍ਰ ਉਚਾਰਾ।","roman":"Tab kannyaa niju pitaa hakaaraa | ih bidhi taa sau mantr uchaaraa |","meaning_en":"Then the daughter called her father, and spoke this counsel to him:","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਤਾਤ ਤਨਿਕ ਚਿੰਤਾ ਨਹਿ ਕਰੀਯੈ। ਸਨਮੁਖ ਪਾਤਿਸਾਹ ਸੌ ਲਰੀਯੈ। ੨੯।","roman":"Taat tanik chintaa nahi kareeyai | sanmukh paatisaah sau lareeyai | 29 |","meaning_en":"'Father, do not worry in the least; fight the emperor face to face.","page":2199,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2199,"meaning_status":"draft"},{"type":"verse","number":[30],"number_text":"੩੦।","page":2199,"lines":[{"gurmukhi":"ਬੋਲ ਸਦਾ ਥਿਰ ਰਹੈ ਦਿਵਸਰੇ ਜਾਇ ਹੈ।","roman":"Bol sadaa thir rahai divasre jaai hai |","meaning_en":"A word stays firm for ever, while the days pass;","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਕਰੇ ਕਰਮ ਛਤ੍ਰਿਨ ਕੇ ਚਾਰਣ ਗਾਇ ਹੈ।","roman":"Kare karam chhatrin ke chaaran gaai hai |","meaning_en":"the bards will sing the deeds of the Kshatriyas.","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਤਾਤ ਨ ਮੋ ਕੋ ਦੀਜੈ ਆਹਵ ਕੀਜਿਯੈ।","roman":"Taat na mo ko deejai aahav keejiyai |","meaning_en":"Father, do not give me; make war;","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਦਾਨ ਕ੍ਰਿਪਾਨ ਦੁਹੂੰ ਜਗ ਮੈ ਜਸ ਲੀਜਿਯੈ। ੩੦।","roman":"Ho daan kripaan duhoon jag mai jas leejiyai | 30 |","meaning_en":"win fame in both worlds, by charity and by the sword.","page":2199,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":2199,"lines":[{"gurmukhi":"ਖੜਗ ਹਾਥ ਜਿਨਿ ਤਜਹੁ ਖੜਗਧਾਰਾ ਸਹੋ।","roman":"Kharag haath jini tajhu kharagdhaaraa saho |","meaning_en":"Do not let the sword fall from your hand; bear the sword's edge;","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਭਾਜਿ ਨ ਚਲਿਯਹੁ ਤਾਤ ਮੰਡਿ ਰਨ ਕੌ ਰਹੋ।","roman":"Bhaaji na chaliyhu taat mandi ran kau raho |","meaning_en":"do not flee, father; stay and hold the battle;","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਪਠੇ ਪਖਰਿਯਾ ਹਨਿਯਹੁ ਬਿਸਿਖ ਪ੍ਰਹਾਰ ਕਰਿ।","roman":"Pathe pakhriyaa haniyhu bisikh prahaar kari |","meaning_en":"send the armoured men and strike with the shower of arrows;","page":2199,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਮਾਰਿ ਅਰਿਨ ਕੌ ਮਰਿਯਹੁ ਹਮਹਿ ਸੰਘਾਰਿ ਕਰਿ। ੩੧।","roman":"Ho maari arin kau mariyhu hamhi sanghaari kari | 31 |","meaning_en":"die after killing the enemy, after destroying us.'","page":2199,"meaning_status":"draft","note":"ਹਮਹਿ ਸੰਘਾਰਿ ਕਰਿ: 'after killing us', as printed; uncertain whether meant to include the women of the house."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2201,"meaning_status":"draft"},{"type":"verse","number":[32],"number_text":"੩੨।","page":2201,"lines":[{"gurmukhi":"ਸੁਨਹੁ ਪਿਤਾ ਇਕ ਕਰਹੁ ਉਪਾਈ। ਸਮਸਦੀਨ ਕਹ ਲੇਹੁ ਬੁਲਾਈ।","roman":"Sunhu pitaa ik karhu upaaee | samasdeen kah lehu bulaaee |","meaning_en":"'Listen, father, devise one remedy: call Shamsuddin;","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਆਵੇ ਤਬ ਪਕਰਿ ਸੰਘਰਿਯਹੁ। ਬਹੁਰੌ ਨਿਕਸਿ ਜੁਧ ਕੌ ਕਰਿਯਹੁ। ੩੨।","roman":"Jab aave tab pakri sanghriyhu | bahurau niksi judh kau kariyhu | 32 |","meaning_en":"when he comes, seize and kill him; then go out and make war.'","page":2201,"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":2201,"lines":[{"gurmukhi":"ਸਿਧ ਪਾਲ ਤਬ ਐਸ ਬਿਚਾਰੀ। ਭਲੀ ਬਾਤ ਇਨ ਸੁਤਾ ਉਚਾਰੀ।","roman":"Sidh paal tab ais bichaaree | bhalee baat in sutaa uchaaree |","meaning_en":"Then Sidh Pal thought thus: 'My daughter has spoken well.'","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਅੰਤਹਪੁਰ ਤੇ ਬਾਹਿਰ ਆਯੋ। ਬੋਲਿ ਪਠਾਨਨ ਐਸ ਜਤਾਯੋ। ੩੩।","roman":"Antahpur te baahir aayo | boli pathaanan ais jataayo | 33 |","meaning_en":"He came out of the inner apartments, called the Pathans and told them thus:","page":2201,"meaning_status":"draft"}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":2201,"lines":[{"gurmukhi":"ਏ ਹੈ ਪ੍ਰਭੁ ਕੇ ਬਡੇ ਬਨਾਏ। ਹਮ ਤੁਮ ਸੇ ਇਨ ਕੇ ਪਗ ਲਾਏ।","roman":"E hai prabhu ke bade banaae | ham tum se in ke pag laae |","meaning_en":"'These are made great by the Lord; you and I serve at their feet.","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਇਨ ਕਹਾ ਵਹੈ ਮਨ ਮਾਨਾ। ਸਿਰ ਪਰ ਹੁਕਮ ਸਾਹ ਕੋ ਆਨਾ। ੩੪।","roman":"Jo in kahaa vahai man maanaa | sir par hukam saah ko aanaa | 34 |","meaning_en":"What they said my mind has accepted; the Shah's order is on my head.'","page":2201,"meaning_status":"draft"}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":2201,"lines":[{"gurmukhi":"ਤਬ ਮਿਲਿ ਖਾਨ ਸਾਹ ਕੇ ਗਏ। ਅਤਿ ਹੀ ਹ੍ਰਿਦੈ ਅਨੰਦਿਤ ਭਏ।","roman":"Tab mili khaan saah ke gae | ati hee hridai anandit bhae |","meaning_en":"Then the Khans went and met the Shah, and were very glad at heart.","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਤੁਰਕਹਿ ਛਤ੍ਰਿਨ ਸੁਤਾ ਨ ਦਈ। ਹਸਿ ਹੈ ਇਨੈ ਭਲੀ ਇਹ ਭਈ। ੩੫।","roman":"Turakhi chhatrin sutaa na daee | hasi hai inai bhalee ih bhaee | 35 |","meaning_en":"'The Kshatriya's daughter was not given to the Turks; they will laugh at these; this has been good.'","page":2201,"meaning_status":"draft","note":"uncertain; line translated as printed and read as the Khans' report."}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":2201,"lines":[{"gurmukhi":"ਦੁਹਿਤਾ ਇਤੈ ਪਿਤਹਿ ਸਮੁਝਾਵੈ। ਛਤ੍ਰੀ ਜਨਮੁ ਫੇਰਿ ਨਹਿ ਆਵੈ।","roman":"Duhitaa itai pithi samujhaavai | chhatree janmu pheri nahi aavai |","meaning_en":"Meanwhile the daughter explained to her father: 'A Kshatriya birth does not come again.","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਅਬ ਲੌ ਐਸੀ ਬਾਤ ਨ ਪਈ। ਤੁਰਕਨ ਕੇ ਛਤ੍ਰਾਨੀ ਗਈ। ੩੬।","roman":"Ab lau aisee baat na paee | turkan ke chhatraanee gaee | 36 |","meaning_en":"Up to now no such thing has been found, that Kshatriya women went to the Turks.","page":2201,"meaning_status":"draft"}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":2201,"lines":[{"gurmukhi":"ਤਾ ਤੇ ਮੋਹਿ ਨ ਦੀਜੈ ਤਾਤਾ। ਮੰਡਹੁ ਜੁਧ ਹੋਤ ਹੀ ਪ੍ਰਾਤਾ।","roman":"Taa te mohi na deejai taataa | mandhu judh hot hee praataa |","meaning_en":"Therefore do not give me, father; wage war when morning comes.","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਚਲਿ ਹੈ ਕਥਾ ਸਦਾ ਜਗ ਮਾਹੀ। ਪ੍ਰਾਤ ਪਠਾਨ ਕਿ ਛਤ੍ਰੀ ਨਾਹੀ। ੩੭।","roman":"Chali hai kathaa sadaa jag maahee | praat pathaan ki chhatree naahee | 37 |","meaning_en":"The story will go on for ever in the world: in the morning, Pathans or Kshatriyas will not be.","page":2201,"meaning_status":"draft","note":"ਪ੍ਰਾਤ ਪਠਾਨ ਕਿ ਛਤ੍ਰੀ ਨਾਹੀ: uncertain."}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":2201,"lines":[{"gurmukhi":"ਪਹਿਰਹੁ ਕੌਚ ਬਜਾਇ ਨਗਾਰੇ। ਪੀ ਪੀ ਅਮਲ ਹੋਹੁ ਮਤਵਾਰੇ।","roman":"Pahirhu kauch bajaai nagaare | pee pee amal hohu matvaare |","meaning_en":"Put on your armour, beat the drums; drink opium again and again and become intoxicated.","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਾਤ ਮਚਤ ਹੈ ਜੁਧ ਅਪਾਰਾ। ਹ੍ਵੈ ਹੈ ਅੰਧ ਧੁੰਧ ਬਿਕਰਾਰਾ। ੩੮।","roman":"Praat machat hai judh apaaraa | hvai hai andh dhundh bikraaraa | 38 |","meaning_en":"In the morning a boundless war will begin; there will be a blind, dark, terrible fray.","page":2201,"meaning_status":"draft"}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":2201,"lines":[{"gurmukhi":"ਪਾਤਿਸਾਹ ਸੰਗ ਹੈ ਸੰਗ੍ਰਾਮਾ। ਸਭ ਹੀ ਕਰਹੁ ਕੇਸਰੀ ਜਾਮਾ।","roman":"Paatisaah sang hai sangraamaa | sabh hee karhu kesree jaamaa |","meaning_en":"The battle will be with the emperor; let all put on saffron robes,","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਟਾਂਕਿ ਆਫੂਐ ਤੁਰੈ ਨਚਾਵੌ। ਸਾਂਗ ਝਲਕਤੀ ਹਾਥ ਫਿਰਾਵੌ। ੩੯।","roman":"Taanki aaphooai turai nachaavau | saang jhalaktee haath phiraavau | 39 |","meaning_en":"make your horses dance, [unclear], and wave the gleaming spear in your hands.","page":2201,"meaning_status":"draft","note":"ਟਾਂਕਿ ਆਫੂਐ: [unclear]."}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":2201,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਤ੍ਯਾਗਿ ਪ੍ਰਾਨਨ ਕੀ ਆਸਾ। ਬਾਹਹੁ ਖੜਗ ਸਕਲ ਤਜਿ ਤ੍ਰਾਸਾ।","roman":"Pratham tyaagi praanan kee aasaa | baahhu kharag sakal taji traasaa |","meaning_en":"First give up the hope of life; wield the sword, leaving all fear;","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਪੋਸਤ ਭਾਂਗ ਅਫੀਮ ਚੜਾਵੋ। ਰੇਤੀ ਮਾਂਝ ਚਰਿਤ੍ਰ ਦਿਖਾਵੋ। ੪੦।","roman":"Posat bhaang apheem charaavo | retee maanjh charitr dikhaavo | 40 |","meaning_en":"take poppy, bhang and opium, and show your prowess in the sand (of the field).","page":2201,"meaning_status":"draft","note":"ਚਰਿਤ੍ਰ here read as 'prowess/deeds'; ਰੇਤੀ read as 'sand'; uncertain."}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":2201,"lines":[{"gurmukhi":"ਹਜਰਤਿ ਜੋਰਿ ਤਹਾ ਦਲ ਆਯੋ। ਸਕਲ ਬ੍ਯਾਹ ਕੋ ਸਾਜ ਬਨਾਯੋ।","roman":"Hajarti jori tahaa dal aayo | sakal byaah ko saaj banaayo |","meaning_en":"The Hazrat came there with his army joined, and made all the wedding arrangements.","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਸਿਧ ਪਾਲ ਕੇ ਜਬ ਘਰਿ ਆਏ। ਪੁਨਿ ਕੰਨ੍ਯਾ ਅਸ ਬਚਨ ਸੁਨਾਏ। ੪੧।","roman":"Sidh paal ke jab ghari aae | puni kannyaa as bachan sunaae | 41 |","meaning_en":"When he came to Sidh Pal's house, the girl again spoke these words:","page":2201,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2201,"meaning_status":"draft"},{"type":"verse","number":[42],"number_text":"੪੨।","page":2201,"lines":[{"gurmukhi":"ਗ੍ਰਿਹ ਆਵੈ ਜੋ ਸਤ੍ਰੁ ਨ ਤਾਹਿ ਸੰਘਾਰਿਯੈ।","roman":"Grih aavai jo satru na taahi sanghaariyai |","meaning_en":"'The enemy who comes to the house, do not kill him then;","page":2201,"meaning_status":"draft"},{"gurmukhi":"ਧਾਮ ਗਏ ਇਹੁ ਮਾਰਹੁ ਮੰਤ੍ਰ ਬਿਚਾਰਿਯੈ।","roman":"Dhaam gae ihu maarhu mantr bichaariyai |","meaning_en":"kill him after he has gone home; consider this counsel.'","page":2201,"meaning_status":"draft","note":"as printed (ਧਾਮ ਗਏ); the sense is uncertain."},{"gurmukhi":"ਲਛਿਮਨ ਪੁਤ੍ਰਹਿ ਡਾਰਿ ਡੋਰਿ ਦਿਯ ਤ੍ਰਿਯ ਉਚਰਿ।","roman":"Lachhiman putrahi daari dori diy triy uchri |","meaning_en":"Putting her son Lachhman into (the litter), the woman spoke;","page":2201,"meaning_status":"draft","note":"ਡਾਰਿ ਡੋਰਿ ਦਿਯ: uncertain; read as 'put into the litter'; the sister's instruction to her brother Lachhman."},{"gurmukhi":"ਹੋ ਸੰਗ ਸਤ ਸੈ ਖਤਿਰੇਟਾ ਗਯੋ ਤ੍ਰਿਯ ਭੇਸ ਧਰਿ। ੪੨।","roman":"Ho sang sat sai khatiretaa gayo triy bhes dhari | 42 |","meaning_en":"the Kshatriya youth went with seven hundred, taking a woman's guise.","page":2201,"meaning_status":"draft","note":"ਖਤਿਰੇਟਾ 'Kshatriya son/youth', as printed."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2203,"meaning_status":"draft"},{"type":"verse","number":[43],"number_text":"੪੩।","page":2203,"lines":[{"gurmukhi":"ਜਬ ਤੇ ਜਾਤ ਧਾਮ ਤੇ ਭਏ। ਤਬ ਤਾ ਕੇ ਮੰਦਰ ਮੋ ਅਏ।","roman":"Jab te jaat dhaam te bhae | tab taa ke mandar mo ae |","meaning_en":"When they left the house, they came into his palace.","page":2203,"meaning_status":"draft"},{"gurmukhi":"ਲੁਬਧਮਾਨ ਹ੍ਵੈ ਹਾਥ ਚਲਾਯੋ। ਲਛਿਮਨ ਕਾਢਿ ਕਟਾਰੀ ਘਾਯੋ। ੪੩।","roman":"Lubadhmaan hvai haath chalaayo | lachhiman kaadhi kataaree ghaayo | 43 |","meaning_en":"Greedy, he stretched out his hand; Lachhman drew a dagger and struck.","page":2203,"meaning_status":"draft"}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":2203,"lines":[{"gurmukhi":"ਤਾਕਹ ਐਸ ਕਟਾਰੀ ਮਾਰਾ। ਬਹੁਰਿ ਨ ਹਜਰਤਿ ਬੈਨ ਉਚਾਰਾ।","roman":"Taakah ais kataaree maaraa | bahuri na hajarti bain uchaaraa |","meaning_en":"He struck him with such a dagger that the Hazrat spoke no word again.","page":2203,"meaning_status":"draft"},{"gurmukhi":"ਤਾਕਹ ਮਾਰਿ ਭੇਸ ਨਰ ਧਾਰੋ। ਲੋਗਨ ਮਹਿ ਇਹ ਭਾਤਿ ਉਚਾਰੋ। ੪੪।","roman":"Taakah maari bhes nar dhaaro | logan mahi ih bhaati uchaaro | 44 |","meaning_en":"Having killed him, they took on men's guise and said this to the people:","page":2203,"meaning_status":"draft"}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":2203,"lines":[{"gurmukhi":"ਮੋਹਿ ਅਮਲ ਕੇ ਕਾਜ ਪਠਾਵਾ। ਤੁਮ ਤਨ ਇਹ ਬਿਧਿ ਆਪੁ ਕਹਾਵਾ।","roman":"Mohi amal ke kaaj pathaavaa | tum tan ih bidhi aapu kahaavaa |","meaning_en":"'He sent me for opium; he himself has told you so.","page":2203,"meaning_status":"draft"},{"gurmukhi":"ਧਾਮ ਆਵਨੇ ਕੋਈ ਨ ਪਾਵੈ। ਜੋ ਆਵੈ ਸੋ ਜਾਨ ਗਵਾਵੈ। ੪੫।","roman":"Dhaam aavne koee na paavai | jo aavai so jaan gavaavai | 45 |","meaning_en":"Let no one come into the house; whoever comes will lose his life.'","page":2203,"meaning_status":"draft"}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":2203,"lines":[{"gurmukhi":"ਇਹ ਛਲ ਲਾਘਿ ਡਵਢੀਯਨ ਆਯੋ। ਚੋਬਦਾਰ ਨਹਿ ਕਿਨੀ ਹਟਾਯੋ।","roman":"Ih chhal laaghi davdheeyan aayo | chobdaar nahi kinee hataayo |","meaning_en":"By this trick he passed the gateways; the mace-bearers did not stop him.","page":2203,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਹੀ ਕੁਮਕ ਆਪਨੀ ਗਯੋ। ਤਬ ਹੀ ਅਮਿਤ ਕੁਲਾਹਲ ਭਯੋ। ੪੬।","roman":"Jab hee kumak aapnee gayo | tab hee amit kulaahal bhayo | 46 |","meaning_en":"As soon as he reached his own reinforcement, then a great uproar arose.","page":2203,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":2203,"lines":[{"gurmukhi":"ਬਾਜੈ ਲਗੇ ਤਹਾ ਸਦਿਯਾਨੇ। ਬਾਜਤ ਤਿਹੂੰ ਭਵਨ ਮਹਿ ਜਾਨੇ।","roman":"Baajai lage tahaa sadiyaane | baajat tihoon bhavan mahi jaane |","meaning_en":"Instruments began to sound there; the sound was known in all three worlds,","page":2203,"meaning_status":"draft"},{"gurmukhi":"ਢੋਲ ਮ੍ਰਿਦੰਗ ਮੁਚੰਗ ਨਗਾਰੇ। ਮੰਦਲ ਤੂਰ ਉਪੰਗ ਅਪਾਰੇ। ੪੭।","roman":"Dhol mridang muchang nagaare | mandal toor upang apaare | 47 |","meaning_en":"drums, mridangs, muchangs, kettledrums, mandals, trumpets and countless upangs.","page":2203,"meaning_status":"draft","note":"instrument names left as printed."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2203,"meaning_status":"draft"},{"type":"verse","number":[48],"number_text":"੪੮।","page":2203,"lines":[{"gurmukhi":"ਬਜੈ ਦਮਾਮਾ ਜਬ ਲਗੇ ਸੁਨਿ ਮਾਰੂ ਧੁਨਿ ਕਾਨ।","roman":"Bajai damaamaa jab lage suni maaroo dhuni kaan |","meaning_en":"As the kettledrum sounded, hearing the Maru sound in their ears,","page":2203,"meaning_status":"draft"},{"gurmukhi":"ਖਾਨ ਖਵੀਨ ਜਿਤੇ ਹੁਤੇ ਟੂਟਿ ਪਰੇ ਤਹ ਆਨਿ। ੪੮।","roman":"Khaan khaveen jite hute tooti pare tah aani | 48 |","meaning_en":"all the Khans and Khavins there were came and pressed in.","page":2203,"meaning_status":"draft","note":"ਖਵੀਨ read as 'chiefs/lords' (khawin); uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2203,"meaning_status":"draft"},{"type":"verse","number":[49],"number_text":"੪੯।","page":2203,"lines":[{"gurmukhi":"ਐਸੋ ਕਵਨ ਦ੍ਵੈਖਨੀ ਜਾਯੋ। ਜਿਨੈ ਜੁਝਊਆ ਇਹਾ ਬਜਾਯੋ।","roman":"Aiso kavan dvaikhnee jaayo | jinai jujhaooaa ihaa bajaayo |","meaning_en":"'What [unclear] son has been born, who has sounded the war-drum here?","page":2203,"meaning_status":"draft","note":"ਦ੍ਵੈਖਨੀ: [unclear]; left untranslated; perhaps a term of abuse."},{"gurmukhi":"ਐਸਾ ਭਯੋ ਕਵਨ ਮਤਵਾਲਾ। ਜਹ ਮੂਰਖ ਨਹਿ ਸੂਝਤ ਚਾਲਾ। ੪੯।","roman":"Aisaa bhayo kavan matvaalaa | jah moorakh nahi soojhat chaalaa | 49 |","meaning_en":"What drunkard is this, where the fool does not see the way things go?'","page":2203,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":2203,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭਾਖਿ ਖਾਨ ਸਭ ਧਾਏ। ਬਾਧੇ ਚੁੰਗ ਚੌਪ ਤਨ ਆਏ।","roman":"Ih bidhi bhaakhi khaan sabh dhaae | baadhe chung chaup tan aae |","meaning_en":"Saying this all the Khans rushed, and came with armour bound on their bodies.","page":2203,"meaning_status":"draft"},{"gurmukhi":"ਸਮਸਦੀਨ ਲਛਿਮਨ ਜਹ ਘਾਯੋ। ਤਿਹ ਠਾ ਸਕਲ ਸੈਨ ਮਿਲਿ ਆਯੋ। ੫੦।","roman":"Samasdeen lachhiman jah ghaayo | tih thaa sakal sain mili aayo | 50 |","meaning_en":"Where Shamsuddin was struck down by Lachhman, there the whole army gathered.","page":2203,"meaning_status":"draft"}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":2203,"lines":[{"gurmukhi":"ਲੋਦੀ ਸੂਰ ਨਯਾਜੀ ਚਲੇ। ਲੀਨੇ ਸੰਗ ਸੂਰਮਾ ਭਲੇ ।","roman":"Lodee soor nayaajee chale | leene sang soormaa bhale |","meaning_en":"Lodi warriors and Niyazis went, taking good fighters with them;","page":2203,"meaning_status":"draft"},{"gurmukhi":"ਦਾਓਜਈ ਰੁਹੇਲੇ ਆਏ। ਆਫਰੀਦਿਯਨ ਤੁਰੈ ਨਚਾਏ। ੫੧।","roman":"Daaojaee ruhele aae | aaphreediyan turai nachaae | 51 |","meaning_en":"Daudzais and Ruhelas came, and Afridis made their horses dance.","page":2203,"meaning_status":"draft","note":"Pathan tribe names."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2203,"meaning_status":"draft"},{"type":"verse","number":[52],"number_text":"੫੨।","page":2203,"lines":[{"gurmukhi":"ਬਾਵਨ ਖੇਲ ਪਠਾਨ ਤਹ ਸਭੈ ਪਰੇ ਅਰਿਰਾਇ।","roman":"Baavan khel pathaan tah sabhai pare ariraai |","meaning_en":"The fifty-two (clans) of the Pathans there all pressed on stubbornly;","page":2203,"meaning_status":"draft","note":"ਬਾਵਨ ਖੇਲ: uncertain; 'fifty-two sports/clans'."},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਬਾਨਾ ਬਧੇ ਗਨਨਾ ਗਨੀ ਨ ਜਾਇ। ੫੨।","roman":"Bhaati bhaati baanaa badhe gannaa ganee na jaai | 52 |","meaning_en":"they tied on garments of many kinds, beyond counting.","page":2203,"meaning_status":"draft","note":"ਬਾਨਾ read as 'dress/gear'."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2203,"meaning_status":"draft"},{"type":"verse","number":[53],"number_text":"੫੩।","page":2203,"lines":[{"gurmukhi":"ਪਖਰਿਯਾਰੇ ਦ੍ਵਾਰਨ ਨਹਿ ਮਾਵੈ। ਜਹਾ ਤਹਾ ਭਟ ਤੁਰੰਗ ਨਚਾਵੈ।","roman":"Pakhriyaare dvaaran nahi maavai | jahaa tahaa bhat turang nachaavai |","meaning_en":"The armoured men could not be contained at the doors; here and there warriors made their horses dance.","page":2203,"meaning_status":"draft"},{"gurmukhi":"ਬਾਨਨ ਕੀ ਆਧੀ ਤਹ ਆਈ। ਹਾਥ ਪਸਾਰਾ ਲਖਾ ਨ ਜਾਈ। ੫੩।","roman":"Baanan kee aadhee tah aaee | haath pasaaraa lakhaa na jaaee | 53 |","meaning_en":"A storm of arrows came; hands stretched out could not be seen.","page":2203,"meaning_status":"draft"}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":2205,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਸੋਰ ਨਗਰ ਮੈ ਪਯੋ। ਜਨੁ ਰਵਿ ਉਲਟਿ ਪਲਟ ਹ੍ਵੈ ਗਯੋ।","roman":"Ih bidhi sor nagar mai payo | janu ravi ulti palat hvai gayo |","meaning_en":"Thus the uproar rose in the city, as if the sun had turned upside down;","page":2205,"meaning_status":"draft"},{"gurmukhi":"ਜੈਸੇ ਜਲਧਿ ਬਾਰਿ ਪਰਹਰੈ। ਉਛਰਿ ਉਛਰਿ ਮਛਰੀ ਜ੍ਯੋ ਮਰੈ। ੫੪।","roman":"Jaise jaldhi baari parahrai | uchhri uchhri machhree jyo marai | 54 |","meaning_en":"as when the ocean throws off its water, and fish leap and die.","page":2205,"meaning_status":"draft"}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":2205,"lines":[{"gurmukhi":"ਜਿਹ ਬਿਧਿ ਨਾਵ ਨਦੀ ਕੀ ਧਾਰਾ। ਬਹੀ ਜਾਤ ਕੋਊ ਨਹਿ ਰਖਵਾਰਾ।","roman":"Jih bidhi naav nadee kee dhaaraa | bahee jaat ko'oo nahi rakhvaaraa |","meaning_en":"As a boat is carried on the current of a river with no one to guard it,","page":2205,"meaning_status":"draft"},{"gurmukhi":"ਤੈਸੀ ਦਸਾ ਨਗਰ ਕੀ ਭਈ। ਜਨੁ ਬਿਨੁ ਸਕ੍ਰ ਸਚੀ ਹ੍ਵੈ ਗਈ। ੫੫।","roman":"Taisee dasaa nagar kee bhaee | janu binu sakr sachee hvai gaee | 55 |","meaning_en":"such became the state of the city, as if Sachi were left without Indra.","page":2205,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2205,"meaning_status":"draft"},{"type":"verse","number":[56],"number_text":"੫੬।","page":2205,"lines":[{"gurmukhi":"ਇਹਿ ਦਿਸਿ ਸਭ ਛਤ੍ਰੀ ਚੜੇ ਉਹਿ ਦਿਸਿ ਚੜੇ ਪਠਾਨ।","roman":"Ihi disi sabh chhatree chare uhi disi chare pathaan |","meaning_en":"On this side all the Kshatriyas advanced, on that side the Pathans.","page":2205,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨਹੁ ਸੰਤ ਚਿਤ ਦੈ ਸਭੈ ਜਿਹ ਬਿਧਿ ਭਯੋ ਨਿਦਾਨ। ੫੬।","roman":"Sunhu sant chit dai sabhai jih bidhi bhayo nidaan | 56 |","meaning_en":"Listen, saints, all of you with attention, how the end came about.","page":2205,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":2205,"meaning_status":"draft"},{"type":"verse","number":[57],"number_text":"੫੭।","page":2205,"lines":[{"gurmukhi":"ਜਬੈ ਜੋਰਿ ਬਾਨਾ ਅਨੀ ਖਾਨ ਆਏ। ਇਤੈ ਛੋਭਿ ਛਤ੍ਰੀ ਸਭੈ ਬੀਰ ਧਾਏ।","roman":"Jabai jori baanaa anee khaan aae | itai chhobhi chhatree sabhai beer dhaae |","meaning_en":"When the Khans came, joining their arrows and ranks, on this side the Kshatriyas, all heroes, rushed on in fury.","page":2205,"meaning_status":"draft","note":"battle passage; sound-words and weapon names left or approximated."},{"gurmukhi":"ਚਲੇ ਬਾਨ ਐਸੇ ਦੁਹੂੰ ਓਰ ਭਾਰੇ। ਲਗੈ ਅੰਗ ਜਾ ਕੇ ਨ ਜਾਹੀ ਨਿਕਾਰੇ। ੫੭।","roman":"Chale baan aise duhoon or bhaare | lagai ang jaa ke na jaahee nikaare | 57 |","meaning_en":"Such heavy arrows flew on both sides that whoever was struck could not pull them out.","page":2205,"meaning_status":"draft"}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":2205,"lines":[{"gurmukhi":"ਤਬੈ ਲਛਿਮਨ ਕੁਮਾਰ ਜੂ ਕੋਪ ਕੈ ਕੈ। ਹਨੇ ਖਾਨ ਬਾਨੀ ਸਭੈ ਸਸਤ੍ਰ ਲੈ ਕੈ।","roman":"Tabai lachhiman kumaar joo kop kai kai | hane khaan baanee sabhai sasatr lai kai |","meaning_en":"Then Prince Lachhman, in anger, took weapons and struck down all the Khans and archers.","page":2205,"meaning_status":"draft","note":"ਬਾਨੀ read as 'archers/men of arrows'; uncertain."},{"gurmukhi":"ਕਿਤੇ ਖੇਤ ਮਾਰੇ ਪਰੇ ਬੀਰ ਐਸੇ। ਬਿਰਾ ਜੈ ਕਟੇ ਇੰਦ੍ਰ ਕੇ ਕੇਤੁ ਜੈਸੇ। ੫੮।","roman":"Kite khet maare pare beer aise | biraa jai kate indr ke ketu jaise | 58 |","meaning_en":"Many heroes lay slain on the field, like the banners of Indra cut down.","page":2205,"meaning_status":"draft"}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":2205,"lines":[{"gurmukhi":"ਪੀਏ ਜਾਨੁ ਭੰਗੈ ਮਲੰਗੈ ਪਰੇ ਹੈ। ਕਹੂੰ ਕੋਟਿ ਸੌਡੀਨ ਸੀਸੈ ਝਰੇ ਹੈ।","roman":"Pee'e jaanu bhangai malangai pare hai | kahoon koti saudeen seesai jhare hai |","meaning_en":"They lay as if drunk on bhang, like mendicants; elsewhere heads of ten million elephants fell.","page":2205,"meaning_status":"draft","note":"ਸੌਡੀਨ read as 'elephants' (trunked ones); uncertain."},{"gurmukhi":"ਕਹੂੰ ਉਸਟ ਮਾਰੇ ਸੁ ਲੈ ਭੂਮਿ ਤੋਪੈ। ਕਹੂੰ ਖੇਤ ਖਾਂਡੇ ਲਸੈ ਨਗਨ ਧੋਪੈ। ੫੯।","roman":"Kahoon usat maare su lai bhoomi topai | kahoon khet khaande lasai nagan dhopai | 59 |","meaning_en":"Elsewhere camels were killed by guns on the ground; elsewhere swords (khandas) gleamed on the field, with countless broad swords.","page":2205,"meaning_status":"draft"}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":2205,"lines":[{"gurmukhi":"ਕਹੂੰ ਬਾਨ ਕਾਟੇ ਪਰੇ ਭੂਮਿ ਐਸੇ। ਬੁਯੋ ਕੋ ਕ੍ਰਿਸਾਨੈ ਕਢੇ ਈਖ ਜੈਸੇ।","roman":"Kahoon baan kaate pare bhoomi aise | buyo ko krisaanai kadhe eekh jaise |","meaning_en":"Elsewhere cut arrows lay on the ground like sugarcane that a farmer pulls out after sowing;","page":2205,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਲਹਿਲਹੈ ਪੇਟ ਮੈ ਯੌ ਕਟਾਰੀ। ਮਨੋ ਮਛ ਸੋਹੈ ਬਧੇ ਬੀਚ ਜਾਰੀ। ੬੦।","roman":"Kahoon lahilhai pet mai yau kataaree | mano machh sohai badhe beech jaaree | 60 |","meaning_en":"elsewhere a dagger waved in a belly, as if a fish shone caught in a net.","page":2205,"meaning_status":"draft"}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":2205,"lines":[{"gurmukhi":"ਕਿਤੈ ਪੇਟ ਪਾਟੇ ਪਰੇ ਖੇਤ ਬਾਜੀ। ਕਹੂੰ ਮਤ ਦੰਤੀ ਫਿਰੈ ਛੂਛ ਤਾਜੀ।","roman":"Kitai pet paate pare khet baajee | kahoon mat dantee phirai chhoochh taajee |","meaning_en":"Elsewhere bellies were torn open, and horses lay on the field; elsewhere mad elephants roamed with empty-saddled horses.","page":2205,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਮੂੰਡ ਮਾਲੀ ਪੁਐ ਮੁੰਡ ਮਾਲਾ। ਕਹੂੰ ਭੂਤ ਔ ਪ੍ਰੇਤ ਨਾਚੈ ਬਿਤਾਲਾ। ੬੧।","roman":"Kahoon moond maalee puai mund maalaa | kahoon bhoot au pret naachai bitaalaa | 61 |","meaning_en":"Elsewhere garlands of heads were strung; elsewhere ghosts, spirits and vetalas danced.","page":2205,"meaning_status":"draft"}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":2205,"lines":[{"gurmukhi":"ਕਹੂੰ ਦੈਤ ਕਾਢੋ ਫਿਰੈ ਦਾਤ ਭਾਰੇ। ਬਮੈ ਸ੍ਰੌਨ ਕੇਤੇ ਪਰੇ ਖੇਤ ਮਾਰੇ।","roman":"Kahoon dait kaadho phirai daat bhaare | bamai sraun kete pare khet maare |","meaning_en":"Elsewhere demons roamed baring great teeth; many vomited blood, lying slain on the field.","page":2205,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਤਾਜਿ ਡਾਰੇ ਜਿਰਹ ਖੋਲ ਐਸੇ। ਬਗੇ ਬ੍ਯੋਤ ਭਾਰੇ ਸਮੈ ਸੀਤ ਜੈਸੇ। ੬੨।","roman":"Kahoon taaji daare jirah khol aise | bage byot bhaare samai seet jaise | 62 |","meaning_en":"Elsewhere horses were cast down, and mail and helmets lay about like [unclear] in the cold season.","page":2205,"meaning_status":"draft","note":"second line uncertain: ਬਗੇ ਬ੍ਯੋਤ ਭਾਰੇ ਸਮੈ ਸੀਤ ਜੈਸੇ; [unclear] in part."}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":2205,"lines":[{"gurmukhi":"ਤਹਾ ਬਾਜ ਹਾਥੀਨ ਕੀ ਸ੍ਰੋਨ ਧਾਰੈ। ਪਰੈ ਜ੍ਯੋ ਫੁਹਾਰਾਨਹੂੰ ਕੀ ਫੁਹਾਰੈ।","roman":"Tahaa baaj haatheen kee sron dhaarai | parai jyo phuhaaraanhoon kee phuhaarai |","meaning_en":"There the blood of horses and elephants flowed and fell like the spray of fountains.","page":2205,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਲੈ ਕਾਲ ਸੋ ਜਾਨ ਦੂਜੋ ਭਯੋ ਹੈ। ਜਹਾ ਕੋਟਿ ਸੂਰਾਨ ਸੂਰਾ ਖਯੋ ਹੈ। ੬੩।","roman":"Pralai kaal so jaan doojo bhayo hai | jahaa koti sooraan sooraa khayo hai | 63 |","meaning_en":"It seemed a second doomsday had come, where ten million warriors of warriors were slain.","page":2205,"meaning_status":"draft"}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":2205,"lines":[{"gurmukhi":"ਤਹਾ ਕੋਟਿ ਸੌਡੀਨ ਕੇ ਸੁੰਡ ਕਾਟੇ। ਕਹੂੰ ਬੀਰ ਮਾਰੇ ਗਿਰੇ ਕੇਤੁ ਫਾਟੇ।","roman":"Tahaa koti saudeen ke sund kaate | kahoon beer maare gire ketu phaate |","meaning_en":"There the trunks of ten million elephants were cut; elsewhere heroes lay slain, their banners torn.","page":2205,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਖੇਤ ਨਾਚੈ ਪਠੇ ਪਖਰਿਯਾਰੇ। ਕਹੂੰ ਮਾਰੂ ਬਾਜੈ ਉਠੈ ਨਾਦ ਭਾਰੇ। ੬੪।","roman":"Kahoon khet naachai pathe pakhriyaare | kahoon maaroo baajai uthai naad bhaare | 64 |","meaning_en":"Elsewhere the armoured men danced on the field; elsewhere the Maru sounded and great sounds rose.","page":2205,"meaning_status":"draft"}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":2207,"lines":[{"gurmukhi":"ਕਹੂੰ ਸੰਖ ਭੇਰੀ ਤਹਾ ਨਾਦ ਬਾਜੈ। ਹਸੈ ਗਰਜਿ ਠੋਕੈ ਭੁਜਾ ਭੂਪ ਗਾਜੈ।","roman":"Kahoon sankh bheree tahaa naad baajai | hasai garji thokai bhujaa bhoop gaajai |","meaning_en":"Elsewhere conch and bheri sounded; kings laughed, roared and slapped their arms.","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਨਗਾਰੇ ਨਫੀਰੀ ਬਜੈ ਝਾਝ ਭਾਰੀ। ਹਠੇ ਰੋਸ ਕੈ ਕੈ ਤਹਾ ਛਤ੍ਰਧਾਰੀ। ੬੫।","roman":"Nagaare napheeree bajai jhaajh bhaaree | hathe ros kai kai tahaa chhatradhaaree | 65 |","meaning_en":"Kettledrums, trumpets and great cymbals sounded; the stubborn umbrella-bearers there were enraged.","page":2207,"meaning_status":"draft"}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":2207,"lines":[{"gurmukhi":"ਕਹੂੰ ਭੀਮ ਭੇਰੀ ਬਜੈ ਰਾਗ ਮਾਰੂ। ਨਫੀਰੀ ਕਹੂੰ ਨਾਇ ਨਾਦੈ ਨਗਾਰੂ।","roman":"Kahoon bheem bheree bajai raag maaroo | napheeree kahoon naai naadai nagaaroo |","meaning_en":"Elsewhere the dread bheri sounded in the raga Maru; elsewhere trumpets and kettledrums boomed.","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਬੇਨੁ ਔ ਬੀਨ ਬਾਜੈ ਸੁਰੰਗਾ। ਰੁਚੰਗਾ ਮ੍ਰਿਦੰਗਾ ਉਪੰਗਾ ਮੁਚੰਗਾ। ੬੬।","roman":"Kahoon benu au been baajai surangaa | ruchangaa mridangaa upangaa muchangaa | 66 |","meaning_en":"Elsewhere flute and vina sounded sweetly; ruchang, mridang, upang and muchang.","page":2207,"meaning_status":"draft","note":"instrument names as printed."}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":2207,"lines":[{"gurmukhi":"ਝਰੋਖਾ ਤਰੇ ਜੋ ਮਚੀ ਮਾਰਿ ਐਸੀ। ਭਈ ਦੇਵ ਦਾਨਵਾਨ ਕੀ ਹੈ ਨ ਤੈਸੀ।","roman":"Jharokhaa tare jo machee maari aisee | bhaee dev daanvaan kee hai na taisee |","meaning_en":"Under the window such a slaughter arose as was not seen between gods and demons;","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਨ ਸ੍ਰੀ ਰਾਮ ਔ ਰਾਵਨੈ ਜੁਧ ਐਸੋ। ਕਿਯੋ ਭੀ ਮਹਾਭਾਰਥੈ ਮੈ ਸੁ ਤੈਸੋ। ੬੭।","roman":"Na sree raam au raavnai judh aiso | kiyo bhee mahaabhaarthai mai su taiso | 67 |","meaning_en":"neither Ram and Ravan fought so, nor was it so in the Mahabharata.","page":2207,"meaning_status":"draft","note":"printed with ਸ੍ਰੀ ਰਾਮ ਔ ਰਾਵਨੈ; the verb ਕਿਯੋ... ਸੁ ਤੈਸੋ read as 'it was done thus'; uncertain."}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":2207,"lines":[{"gurmukhi":"ਤਹਾ ਬੀਰ ਕੇਤੇ ਖਰੇ ਗਾਲ੍ਹ ਮਾਰੈ। ਕਿਤੇ ਬਾਨ ਛੋਡੈ ਕਿਤੈ ਸਸਤ੍ਰ ਧਾਰੈ।","roman":"Tahaa beer kete khare gaalh maarai | kite baan chhodai kitai sasatr dhaarai |","meaning_en":"There many heroes stood abusing one another; some loosed arrows, some bore weapons;","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਨਾਰ ਕੇ ਭੇਸ ਕੌ ਸਾਜ ਲੈਕੈ। ਚਲੈ ਛੋਰਿ ਬਾਜੀ ਹਠੀ ਭਾਜ ਕੈਕੈ। ੬੮।","roman":"Kite naar ke bhes kau saaj laikai | chalai chhori baajee hathee bhaaj kaikai | 68 |","meaning_en":"some, taking up the dress of women, left their horses and fled in haste.","page":2207,"meaning_status":"draft"}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":2207,"lines":[{"gurmukhi":"ਕਿਤੇ ਖਾਨ ਖੇਦੇ ਕਿਤੇ ਖੇਤ ਮਾਰੇ। ਕਿਤੇ ਖੇਤ ਮੈ ਖਿੰਗ ਖਤ੍ਰੀ ਲਤਾਰੇ।","roman":"Kite khaan khede kite khet maare | kite khet mai khing khatree lataare |","meaning_en":"Some Khans were chased, some slain on the field; some grey-horsed Kshatriyas were trampled on the field.","page":2207,"meaning_status":"draft","note":"ਖਿੰਗ read as 'grey horse'; uncertain."},{"gurmukhi":"ਜਹਾ ਬੀਰ ਬਾਂਕੇ ਹਠੀ ਪੂਤ ਘਾਏ। ਤਹੀ ਗੋਲ ਬਾਧੇ ਚਲੇ ਸਿਧ ਆਏ। ੬੯।","roman":"Jahaa beer baanke hathee poot ghaae | tahee gol baadhe chale sidh aae | 69 |","meaning_en":"Where stalwart, stubborn sons were struck, there, bound in bands, Sidh Pal's men came.","page":2207,"meaning_status":"draft"}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":2207,"lines":[{"gurmukhi":"ਜਬੈ ਸਿਧ ਪਾਲੈ ਪਠਾਨੌ ਨਿਹਾਰਾ। ਕਿਨੀ ਹਾਥ ਲੈ ਨ ਹਥ੍ਯਾਰੈ ਸੰਭਾਰਾ।","roman":"Jabai sidh paalai pathaanau nihaaraa | kinee haath lai na hathyaarai sanbhaaraa |","meaning_en":"When Sidh Pal saw the Pathans, none took a weapon in hand or held it steady;","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਭਾਜਿ ਚਾਲੇ ਕਿਤੇ ਖੇਤ ਮਾਰੇ। ਪੁਰਾਨੇ ਪਲਾਸੀ ਮਨੋ ਬਾਇ ਡਾਰੇ। ੭੦।","roman":"Kite bhaaji chaale kite khet maare | puraane palaasee mano baai daare | 70 |","meaning_en":"some fled, some were slain, like old palasi trees thrown down by the wind.","page":2207,"meaning_status":"draft"}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":2207,"lines":[{"gurmukhi":"ਹਠੇ ਜੇ ਜੁਝੇ ਸੇ ਸਭੈ ਖੇਤ ਮਾਰੇ। ਕਿਤੇ ਖੇਦਿ ਕੈ ਕੋਟ ਕੇ ਮਧਿ ਡਾਰੇ।","roman":"Hathe je jujhe se sabhai khet maare | kite khedi kai kot ke madhi daare |","meaning_en":"The stubborn ones who fought were all killed; some were chased and thrown inside the fort;","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਬਾਧਿ ਲੈ ਕੈ ਕਿਤੇ ਛੋਰਿ ਦੀਨੇ। ਕਿਤੇ ਜਾਨ ਮਾਰੇ ਕਿਤੇ ਰਾਖਿ ਲੀਨੇ। ੭੧।","roman":"Kite baadhi lai kai kite chhori deene | kite jaan maare kite raakhi leene | 71 |","meaning_en":"some were bound and taken, some released; some were killed, some spared.","page":2207,"meaning_status":"draft"}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":2207,"lines":[{"gurmukhi":"ਤਿਸੀ ਕੌ ਹਨਾ ਖਗ ਜੌਨੇ ਉਚਾਯੋ। ਸੋਈ ਜੀਵ ਬਾਚਾ ਜੁਈ ਭਾਜਿ ਆਯੋ।","roman":"Tisee kau hanaa khag jaune uchaayo | soee jeev baachaa juee bhaaji aayo |","meaning_en":"Whoever raised a sword was struck; whoever ran away saved his life.","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਲੌ ਗਨਾਊ ਭਯੋ ਜੁਧ ਭਾਰੀ। ਲਖੇ ਲੋਹ ਮਾਚਾ ਕੁਪੇ ਛਤ੍ਰ ਧਾਰੀ। ੭੨।","roman":"Kahaa lau ganaaoo bhayo judh bhaaree | lakhe loh maachaa kupe chhatr dhaaree | 72 |","meaning_en":"How much shall I count? A great war was fought; at the sight of iron the umbrella-bearers raged.","page":2207,"meaning_status":"draft"}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":2207,"lines":[{"gurmukhi":"ਕਿਤੇ ਨਾਦ ਨਾਦੈ ਕਿਤੇ ਨਾਦ ਪੂਰੈ। ਕਿਤੇ ਜ੍ਵਾਨ ਜੂਝੈ ਬਰੈ ਹੇਰਿ ਸੂਰੈ।","roman":"Kite naad naadai kite naad poorai | kite jvaan joojhai barai heri soorai |","meaning_en":"Some sounded horns, some blew them; some youths fought and were wed to apsaras, seeing them.","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਆਨਿ ਕੈ ਕੈ ਕ੍ਰਿਪਾਨੈ ਚਲਾਵੈ। ਕਿਤੇ ਆਨਿ ਗਾਜੈ ਕਿਤੇ ਭਾਜਿ ਜਾਵੈ। ੭੩।","roman":"Kite aani kai kai kripaanai chalaavai | kite aani gaajai kite bhaaji jaavai | 73 |","meaning_en":"Some came and plied swords; some came and roared; some ran away.","page":2207,"meaning_status":"draft"}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":2207,"lines":[{"gurmukhi":"ਜਬੈ ਸਿਧ ਪਾਲੈ ਸਭੈ ਖਾਨ ਮਾਰੇ। ਲਏ ਛੀਨ ਕੈ ਤਾਜ ਬਾਜੀ ਨਗਾਰੇ।","roman":"Jabai sidh paalai sabhai khaan maare | lae chheen kai taaj baajee nagaare |","meaning_en":"When Sidh Pal had killed all the Khans, he snatched their crowns, horses and drums.","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਹੁਤੇ ਦੂਰਿ ਬਾਸੀ ਕਿਤੇ ਖਾਨ ਘਾਏ। ਘਿਰਿਯੋ ਸਿਧ ਪਾਲੈ ਕਰੀ ਮਤ ਨ੍ਯਾਏ। ੭੪।","roman":"Hute doori baasee kite khaan ghaae | ghiriyo sidh paalai karee mat nyaae | 74 |","meaning_en":"Some Khans who lived far off were slain; Sidh Pal, surrounded, [unclear] justice.","page":2207,"meaning_status":"draft","note":"ਕਰੀ ਮਤ ਨ੍ਯਾਏ: uncertain (perhaps 'made mad justice'); printed so."}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":2207,"lines":[{"gurmukhi":"ਜਿਤੇ ਖਾਨ ਭਾਜੇ ਤਿਤੇ ਫੇਰਿ ਢੂਕੇ। ਚਹੂੰ ਓਰ ਗਾਜੈ ਹਠੀ ਸਿਧ ਜੂ ਕੇ।","roman":"Jite khaan bhaaje tite pheri dhooke | chahoon or gaajai hathee sidh joo ke |","meaning_en":"As many Khans as had fled, so many came back; the stubborn men of Sidh roared on all sides.","page":2207,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਜਾਇਗੋ ਛਤ੍ਰਿ ਜਾਨੇ ਨ ਦੈਹੈ। ਇਹੀ ਛੇਤ੍ਰ ਮੈ ਛਿਪ੍ਰ ਤੁਹਿ ਅਜੁ ਛੈਹੈ। ੭੫।","roman":"Kahaa jaaigo chhatri jaane na daihai | ihee chhetr mai chhipr tuhi aju chhaihai | 75 |","meaning_en":"'Where will you go? The Kshatriyas will not let you go; in this field I will quickly destroy you today.'","page":2207,"meaning_status":"draft"}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":2209,"lines":[{"gurmukhi":"ਸੁਨੇ ਬੈਨ ਐਸੇ ਭਰਿਯੋ ਕੋਪ ਸੂਰੋ। ਸਭੇ ਸਸਤ੍ਰ ਸੌਡੀ ਮਹਾ ਲੋਹ ਪੂਰੋ।","roman":"Sune bain aise bhariyo kop sooro | sabhe sasatr saudee mahaa loh pooro |","meaning_en":"Hearing such words the warrior was filled with rage; all his weapons were of great iron.","page":2209,"meaning_status":"draft"},{"gurmukhi":"ਦਯੋ ਸੈਨ ਕੌ ਆਇਸੈ ਆਪੁ ਹੀ ਯੋ। ਕਪੀ ਬਾਹਨੀ ਕੌ ਕਹਿਯੋ ਰਾਮ ਜੀ ਯੋ। ੭੬।","roman":"Dayo sain kau aaisai aapu hee yo | kapee baahnee kau kahiyo raam jee yo | 76 |","meaning_en":"He himself gave the army its order, as Ram spoke to the army of monkeys.","page":2209,"meaning_status":"draft"}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":2209,"lines":[{"gurmukhi":"ਸੁਨੇ ਬੈਨ ਸੈਨਾ ਚਲੀ ਕੋਪ ਕੈ ਕੈ। ਸਭੇ ਸਸਤ੍ਰ ਅਸਤ੍ਰਾਨ ਕੌ ਹਾਥ ਲੈ ਕੈ।","roman":"Sune bain sainaa chalee kop kai kai | sabhe sasatr astraan kau haath lai kai |","meaning_en":"Hearing his words the army advanced in anger, taking in hand all arms and missiles.","page":2209,"meaning_status":"draft"},{"gurmukhi":"ਜਿਤੇ ਖਾਨ ਆਏ ਤਿਤੇ ਖੇਤ ਮਾਰੇ। ਕਿਤੇ ਖੇਦਿ ਕੈ ਕੋਟਿ ਕੀ ਓਟ ਡਾਰੇ। ੭੭।","roman":"Jite khaan aae tite khet maare | kite khedi kai koti kee ot daare | 77 |","meaning_en":"As many Khans as came were killed on the field; some were chased and thrown behind the fort wall.","page":2209,"meaning_status":"draft"}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":2209,"lines":[{"gurmukhi":"ਕਿਤੇ ਬੀਰ ਬਾਨੈਤ ਬਾਜੀ ਪਲਟੈ। ਕਿਤੇ ਬੀਰ ਬਾਨੀਨ ਸੋ ਆਨਿ ਜੁਟੈ।","roman":"Kite beer baanait baajee paltai | kite beer baaneen so aani jutai |","meaning_en":"Some heroes turned their horses on the spearmen; some heroes closed in with the archers.","page":2209,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਖਗ ਲੈ ਖਿੰਗ ਖਤ੍ਰੀ ਉਮੰਗੈ। ਜਹਾ ਜੰਗ ਜੋਧਾ ਜਗੇ ਜੋਰ ਜੰਗੈ। ੭੮।","roman":"Kite khag lai khing khatree umangai | jahaa jang jodhaa jage jor jangai | 78 |","meaning_en":"Some Kshatriyas, with swords, were eager; where warriors awake in battle, the fray was fierce.","page":2209,"meaning_status":"draft"}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":2209,"lines":[{"gurmukhi":"ਘੁਰੈ ਘੋਰ ਬਾਦਿਤ੍ਰ ਮਾਰੂ ਨਗਾਰੇ। ਮਚੇ ਆਨਿ ਕੈ ਕੈ ਮਹਾ ਭੂਪ ਭਾਰੇ।","roman":"Ghurai ghor baaditr maaroo nagaare | mache aani kai kai mahaa bhoop bhaare |","meaning_en":"Terrible instruments boomed, the Maru drums; great kings pressed in and joined battle.","page":2209,"meaning_status":"draft"},{"gurmukhi":"ਖੁਲੇ ਖਗ ਖਤ੍ਰੀ ਉਠੇ ਭਾਤਿ ਐਸੀ। ਮਨੋ ਬਹਨਿ ਜ੍ਵਾਲਾ ਪ੍ਰਲੈ ਕਾਲ ਜੈਸੀ। ੭੯।","roman":"Khule khag khatree uthe bhaati aisee | mano bahni jvaalaa pralai kaal jaisee | 79 |","meaning_en":"Drawn swords of the Kshatriyas rose in such manner as if the flame of fire at the time of dissolution.","page":2209,"meaning_status":"draft"}]},{"type":"verse","number":[80],"number_text":"੮੦।","page":2209,"lines":[{"gurmukhi":"ਕਹੂੰ ਟੀਕ ਕਾਟੇ ਗਿਰੇ ਟੋਪ ਟੂਟੇ। ਕਹੂੰ ਤਾਜ ਧਾਰੀ ਪਰੇ ਬਰਮ ਛੂਟੇ।","roman":"Kahoon teek kaate gire top toote | kahoon taaj dhaaree pare baram chhoote |","meaning_en":"Elsewhere foreheads were cut, helmets broken; elsewhere crown-wearers lay, their armour undone;","page":2209,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਚਰਮ ਕਾਟੇ ਪਰੇ ਖੇਤ ਐਸੇ। ਕਹੂੰ ਚੌਰ ਸੋਹੈ ਮਨੋ ਹੰਸ ਜੈਸੇ। ੮੦।","roman":"Kahoon charam kaate pare khet aise | kahoon chaur sohai mano hans jaise | 80 |","meaning_en":"elsewhere shields cut lay on the field; elsewhere fly-whisks shone like swans.","page":2209,"meaning_status":"draft"}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":2209,"lines":[{"gurmukhi":"ਕਹੂੰ ਕੇਤੁ ਕਾਟੇ ਲਸੇ ਭੂਮ ਐਸੇ। ਮਨੋ ਬਾਯ ਤੋਰੇ ਮਹਾ ਬ੍ਰਿਛ ਜੈਸੇ।","roman":"Kahoon ketu kaate lase bhoom aise | mano baay tore mahaa brichh jaise |","meaning_en":"Elsewhere cut banners lay shining on the ground, like great trees broken by the wind;","page":2209,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਅਰਧ ਕਾਟੇ ਤੁਰੰਗੈ ਝਰੇ ਹੈ। ਕਹੂੰ ਟੂਕ ਟੂਕ ਹ੍ਵੈ ਮਤੰਗੇ ਪਰੇ ਹੈ। ੮੧।","roman":"Kahoon aradh kaate turangai jhare hai | kahoon took took hvai matange pare hai | 81 |","meaning_en":"elsewhere horses lay cut in half, and elephants in pieces.","page":2209,"meaning_status":"draft"}]},{"type":"verse","number":[82],"number_text":"੮੨।","page":2209,"lines":[{"gurmukhi":"ਕਿਤੇ ਡੋਬ ਡੂਬੇ ਗਿਰੇ ਘੂੰਮ ਘੂੰਮੈ। ਗਜੈ ਰਾਜ ਬਾਜੀ ਹਨੇ ਭੂਮਿ ਝੂੰਮੈ।","roman":"Kite dob doobe gire ghoonm ghoonmai | gajai raaj baajee hane bhoomi jhoonmai |","meaning_en":"Some, drowned in the fray, fell and whirled; kings roared; horses were slain and rolled on the ground.","page":2209,"meaning_status":"draft","note":"uncertain; ਡੋਬ ਡੂਬੇ."},{"gurmukhi":"ਕਿਤੇ ਊਠਿ ਭਾਜੇ ਦੁਰੇ ਬੂਟ ਮਾਹੀ। ਲਗੈ ਘਾਵ ਪੀਠੈ ਕਢੇ ਮੂੰਡ ਨਾਹੀ। ੮੨।","roman":"Kite oothi bhaaje dure boot maahee | lagai ghaav peethai kadhe moond naahee | 82 |","meaning_en":"Some fled and hid in bushes; wounds fell on their backs, but not on their heads.","page":2209,"meaning_status":"draft"}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":2209,"lines":[{"gurmukhi":"ਕਿਤ੍ਯੋ ਕੇਸੁ ਫਾਸੇ ਦ੍ਰੁਮੋ ਜਾਤ ਜੋਰੈ। ਹਹਾ ਮੋਹਿ ਛਾਡੈ ਕਹੈ ਸਤ੍ਰੁ ਭੋਰੈ।","roman":"Kityo kesu phaase drumo jaat jorai | hahaa mohi chhaadai kahai satru bhorai |","meaning_en":"Some were caught by the hair in trees, and joined their hands: 'Alas, let me go,' they cry to the enemy at dawn.","page":2209,"meaning_status":"draft","note":"ਭੋਰੈ read as 'at dawn/in simplicity'; uncertain."},{"gurmukhi":"ਨਿਕਾਰੈ ਕ੍ਰਿਪਾਨੈ ਨ ਪਾਛੈ ਨਿਹਾਰੈ। ਭਜੇ ਜਾਹਿ ਕਾਜੀ ਨ ਬਾਜੀ ਸੰਭਾਰੈ। ੮੩।","roman":"Nikaarai kripaanai na paachhai nihaarai | bhaje jaahi kaajee na baajee sanbhaarai | 83 |","meaning_en":"They draw their swords, and do not look behind; they flee, and the Qazi does not control his horse.","page":2209,"meaning_status":"draft"}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":2209,"lines":[{"gurmukhi":"ਕਿਤੇ ਖਾਨ ਤੋਰੇ ਨ ਘੋਰੇ ਸੰਭਾਰੈ। ਕਿਤੇ ਛੋਰਿ ਜੋਰੇ ਤ੍ਰਿਯਾ ਭੇਸ ਧਾਰੈ।","roman":"Kite khaan tore na ghore sanbhaarai | kite chhori jore triyaa bhes dhaarai |","meaning_en":"Some Khans broke away and did not hold their horses; some left them, joined hands, and took on women's guise.","page":2209,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੈ ਦੈ ਅਕੋਰੈ ਨਿਹੋਰੈ ਤਿਸੀ ਕੌ। ਲਏ ਹਾਥ ਮੈ ਤੇਗ ਦੇਖੈ ਜਿਸੀ ਕੌ। ੮੪।","roman":"Kitai dai akorai nihorai tisee kau | lae haath mai teg dekhai jisee kau | 84 |","meaning_en":"Some, embracing, called out to him whom they saw with a sword in hand.","page":2209,"meaning_status":"draft","note":"uncertain: ਦੈ ਅਕੋਰੈ ਨਿਹੋਰੈ."}]},{"type":"verse","number":[85],"number_text":"੮੫।","page":2209,"lines":[{"gurmukhi":"ਕਿਤੇ ਜੀਵ ਲੈ ਕੇ ਸਿਪਾਹੀ ਸਿਧਾਏ। ਕਿਤੇ ਚੁੰਗ ਬਾਧੈ ਚਲੈ ਖੇਤ ਆਏ।","roman":"Kite jeev lai ke sipaahee sidhaae | kite chung baadhai chalai khet aae |","meaning_en":"Some soldiers went away with their lives; some, with armour tied, came to the field.","page":2209,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤ੍ਯੋ ਪ੍ਰਾਨ ਹੋਮੇ ਰਨਹਿ ਜ੍ਵਾਲ ਮਾਹੀ। ਮਰੈ ਟੂਕ ਟੂਕ ਹ੍ਵੈ ਭਜੈ ਪੈ ਗੁਨਾ ਹੀ। ੮੫।","roman":"Kityo praan home ranhi jvaal maahee | marai took took hvai bhajai pai gunaa hee | 85 |","meaning_en":"Some offered their lives into the flame of war; they die in pieces, or flee, but [unclear].","page":2209,"meaning_status":"draft","note":"ਪੈ ਗੁਨਾ ਹੀ: [unclear]."}]},{"type":"verse","number":[86],"number_text":"੮੬।","page":2211,"lines":[{"gurmukhi":"ਤਹਾ ਲੈ ਅਪਛ੍ਰਾਨ ਕੇਤੇ ਬਰੇ ਹੈ। ਜਿਤੇ ਸਾਮੁਹੇ ਜੁਧ ਕੈ ਕੈ ਮਰੇ ਹੈ।","roman":"Tahaa lai apchhraan kete bare hai | jite saamuhe judh kai kai mare hai |","meaning_en":"There many apsaras took husbands, of all who died fighting face to face.","page":2211,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਨਰਕ ਬਾਸੀ ਤਿਸੀ ਕਾਲ ਹੂਏ। ਜਿਤੇ ਸੂਮ ਸੋਫੀ ਭਜੇ ਜਾਤ ਮੂਏ। ੮੬।","roman":"Kite narak baasee tisee kaal hooe | jite soom sophee bhaje jaat mooe | 86 |","meaning_en":"Many at that time became dwellers of hell, who fled, mean and cowardly, and died.","page":2211,"meaning_status":"draft"}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":2211,"lines":[{"gurmukhi":"ਕਿਤੇ ਭੀਰੂ ਜੋਧਾ ਮਰੇ ਬਾਜ ਮਾਰੇ। ਗਿਰੇ ਤ੍ਰਾਸ ਕੈ ਕੈ ਬਿਨਾ ਬਾਨ ਡਾਰੇ।","roman":"Kite bheeroo jodhaa mare baaj maare | gire traas kai kai binaa baan daare |","meaning_en":"Many timid warriors died, killed by hawks; they fell in terror without shooting an arrow.","page":2211,"meaning_status":"draft","note":"ਬਾਜ ਮਾਰੇ: uncertain ('killed by hawks' or 'killed by horses')."},{"gurmukhi":"ਕਿਤ੍ਯੋ ਅਗਮਨੈ ਆਨਿ ਕੈ ਪ੍ਰਾਨ ਦੀਨੇ। ਕਿਤ੍ਯੋ ਦੇਵ ਕੇ ਲੋਕ ਕੋ ਪੰਥ ਲੀਨੇ। ੮੭।","roman":"Kityo agamnai aani kai praan deene | kityo dev ke lok ko panth leene | 87 |","meaning_en":"Many came forward and gave their lives; many took the path to the world of the gods.","page":2211,"meaning_status":"draft"}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":2211,"lines":[{"gurmukhi":"ਜਿਤੇ ਸੂਮ ਸੋਫੀ ਭਜੇ ਜਾਤ ਮਾਰੇ। ਤਿਤੇ ਭੂਮਿ ਭੋਗੈ ਨਹੀ ਬੰਨਿ ਜਾਰੇ।","roman":"Jite soom sophee bhaje jaat maare | tite bhoomi bhogai nahee banni jaare |","meaning_en":"As many mean cowards as fled and were killed, so many will not enjoy the earth, nor [unclear].","page":2211,"meaning_status":"draft","note":"ਬੰਨਿ ਜਾਰੇ: [unclear]."},{"gurmukhi":"ਭਈ ਭੀਰ ਗਾਢੀ ਮਚਿਯੋ ਜੁਧ ਭਾਰੀ। ਲਖੀੇ ਬੀਰ ਠਾਢੇ ਕਪੈ ਦੇਹ ਸਾਰੀ। ੮੮।","roman":"Bhaee bheer gaadhee machiyo judh bhaaree | lakhe beer thaadhe kapai deh saaree | 88 |","meaning_en":"The crowd thickened and a great war raged; seeing it, the heroes stood, their whole bodies trembling.","page":2211,"meaning_status":"draft"}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":2211,"lines":[{"gurmukhi":"ਜਹਾ ਸਿਧ ਪਾਲੈ ਘਨੇ ਸਤ੍ਰ ਕੂਟੇ। ਤਹਾ ਦੇਖਿ ਜੋਧਾਨ ਤੈ ਕੋਟਿ ਛੂਟੇ।","roman":"Jahaa sidh paalai ghane satr koote | tahaa dekhi jodhaan tai koti chhoote |","meaning_en":"Where Sidh Pal crushed many enemies, seeing it, ten million warriors broke and fled.","page":2211,"meaning_status":"draft"},{"gurmukhi":"ਚਲੇ ਭਾਜਿ ਕੈ ਨ ਹਥ੍ਯਾਰੈ ਸੰਭਾਰਿਯੋ। ਲਖੈ ਸਮਸਦੀਨੈ ਪਰਿਯੋ ਭੂੰਮਿ ਮਾਰਿਯੋ। ੮੯।","roman":"Chale bhaaji kai na hathyaarai sanbhaariyo | lakhai samasdeenai pariyo bhoonmi maariyo | 89 |","meaning_en":"They fled, no one holding a weapon; Shamsuddin was seen lying killed on the ground.","page":2211,"meaning_status":"draft"}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":2211,"lines":[{"gurmukhi":"ਤਹਾ ਭਾਟ ਢਾਢੀ ਖਰੇ ਗੀਤ ਗਾਵੈ। ਸੁਨਾਵੈ ਪ੍ਰਭੈ ਬੈਰ ਬ੍ਰਿੰਦੈ ਤ੍ਰਸਾਵੈ।","roman":"Tahaa bhaat dhaadhee khare geet gaavai | sunaavai prabhai bair brindai trasaavai |","meaning_en":"There bards and minstrels stood singing songs, and told of the Lord's enmity, terrifying multitudes.","page":2211,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਨਾਦ ਬਾਜੈ ਨਫੀਰੀ ਨਗਾਰੇ। ਹਸੈ ਗਰਜਿ ਠੋਕੈ ਭੁਜਾ ਭੂਪ ਭਾਰੇ। ੯੦।","roman":"Kahoon naad baajai napheeree nagaare | hasai garji thokai bhujaa bhoop bhaare | 90 |","meaning_en":"Elsewhere horns, trumpets and kettledrums sounded; great kings laughed, roared and slapped their arms.","page":2211,"meaning_status":"draft"}]},{"type":"verse","number":[91],"number_text":"੯੧।","page":2211,"lines":[{"gurmukhi":"ਜਬੈ ਖਾਨ ਜੂਝੈ ਸਭੈ ਖੇਤ ਮਾਹੀ। ਬਡੇ ਐਠਿਯਾਰੇ ਬਚਿਯੋ ਏਕ ਨਾਹੀ।","roman":"Jabai khaan joojhai sabhai khet maahee | bade aithiyaare bachiyo ek naahee |","meaning_en":"When all the Khans were slain in the field, of the great proud ones not one was left;","page":2211,"meaning_status":"draft"},{"gurmukhi":"ਲਈ ਛੀਨਿ ਦਿਲੀ ਦਿਲੀਸੈ ਸੰਘਾਰਿਯੋ। ਤਬੈ ਆਪਨੇ ਸੀਸ ਪੈ ਛਤ੍ਰ ਢਾਰਿਯੋ। ੯੧।","roman":"Laee chheeni dilee dileesai sanghaariyo | tabai aapne sees pai chhatr dhaariyo | 91 |","meaning_en":"he snatched Delhi and killed the lord of Delhi; then he held the royal umbrella over his own head.","page":2211,"meaning_status":"draft"}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":2211,"lines":[{"gurmukhi":"ਜਬੈ ਸਿਧ ਪਾਲੈ ਘਨੀ ਸੈਨ ਕੂਟੀ। ਬਚੈ ਪ੍ਰਾਨ ਲੈ ਕੈ ਚਹੂੰ ਓਰ ਫੂਟੀ।","roman":"Jabai sidh paalai ghanee sain kootee | bachai praan lai kai chahoon or phootee |","meaning_en":"When Sidh Pal crushed the great army, those who saved their lives scattered in four directions;","page":2211,"meaning_status":"draft"},{"gurmukhi":"ਲਈ ਪਾਤਿਸਾਹੀ ਸਿਰੈ ਛਤ੍ਰ ਢਾਰਿਯੋ। ਪਰਿਯੋ ਪਾਸੁ ਬਾਚ੍ਯੋ ਅਰਿਯੋ ਸੋ ਸੰਘਾਰਿਯੋ। ੯੨।","roman":"Laee paatisaahee sirai chhatr dhaariyo | pariyo paasu baachyo ariyo so sanghaariyo | 92 |","meaning_en":"he took the empire and put the umbrella over his head; whoever fell near him survived, and whoever opposed was killed.","page":2211,"meaning_status":"draft"}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":2211,"lines":[{"gurmukhi":"ਲਈ ਪਾਤਸਾਹੀ ਹ੍ਰਿਦੈ ਯੌ ਬਿਚਾਰਾ। ਕਰਿਯੋ ਕਾਜ ਨੀਕੋ ਨ ਸਾਹੈ ਸੰਘਾਰਾ।","roman":"Laee paatsaahee hridai yau bichaaraa | kariyo kaaj neeko na saahai sanghaaraa |","meaning_en":"He took the emperorship, and thought in his heart, 'I have done well; I killed the Shah.'","page":2211,"meaning_status":"draft","note":"printed ਨ ਸਾਹੈ; read as 'killed the Shah'."},{"gurmukhi":"ਜਗ੍ਯੋ ਰੈਨਿ ਸਾਰੀ ਧਰਿਯੋ ਧ੍ਯਾਨ ਤਾ ਕੋ। ਦਿਯੋ ਪਾਤਿਸਾਹੀ ਮਿਲੈ ਪ੍ਰਾਤ ਵਾ ਕੋ। ੯੩।","roman":"Jagyo raini saaree dhariyo dhyaan taa ko | diyo paatisaahee milai praat vaa ko | 93 |","meaning_en":"He stayed awake all night in meditation on Him, and resolved: 'I will give the empire in the morning to the one who meets me.'","page":2211,"meaning_status":"draft","note":"second line uncertain."}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":2211,"lines":[{"gurmukhi":"ਕਸਾਈਨ ਕੌ ਦਾਸ ਤਹ ਏਕ ਆਯੋ। ਨਦੀ ਡਾਰਬੇ ਓਝਰੀ ਲੈ ਸਿਧਾਯੋ।","roman":"Kasaaeen kau daas tah ek aayo | nadee daarbe ojhree lai sidhaayo |","meaning_en":"A butchers' slave came there, going to throw offal into the river.","page":2211,"meaning_status":"draft","note":"ਓਝਰੀ read as 'offal/tripe'; uncertain."},{"gurmukhi":"ਗਹਿਯੋ ਜਾਹਿ ਤਾ ਕੋ ਦਈ ਪਾਤਿਸਾਹੀ। ਧਰਿਯੋ ਜੈਨ ਆਲਾਵਦੀ ਨਾਮ ਤਾਹੀ। ੯੪।","roman":"Gahiyo jaahi taa ko daee paatisaahee | dhariyo jain aalaavdee naam taahee | 94 |","meaning_en":"He seized him and gave him the empire, and gave him the name Jain Alavadi.","page":2211,"meaning_status":"draft","note":"name as printed, perhaps for Zain/Alauddin; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2211,"meaning_status":"draft"},{"type":"verse","number":[95],"number_text":"੯੫।","page":2211,"lines":[{"gurmukhi":"ਜਬ ਹੀ ਰਾਜ ਤਵਨ ਕਹ ਦਯੋ। ਸੁਤਾ ਸਹਿਤ ਬਨ ਮਾਰਗ ਲਯੋ।","roman":"Jab hee raaj tavan kah dayo | sutaa sahit ban maarag layo |","meaning_en":"As soon as he had given him the rule, he took the forest road with his daughter.","page":2211,"meaning_status":"draft"},{"gurmukhi":"ਬਦ੍ਰਕਾਸਿ ਮਹਿ ਕਿਯਾ ਪ੍ਰਵੇਸਾ। ਦੁਹਿਤਾ ਸਹਿਤ ਅਤਿਥ ਕੇ ਭੇਸਾ। ੯੫।","roman":"Badrakaasi mahi kiyaa pravesaa | duhitaa sahit atith ke bhesaa | 95 |","meaning_en":"He entered Badrikashi, with his daughter, in the garb of ascetics.","page":2211,"meaning_status":"draft","note":"ਬਦ੍ਰਕਾਸਿ: Badri (Badrinath) region, as printed."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2211,"meaning_status":"draft"},{"type":"verse","number":[96],"number_text":"੯੬।","page":2211,"lines":[{"gurmukhi":"ਜਬ ਬਹੁ ਤਹ ਤਪਸਾ ਕਰੀ ਪ੍ਰਗਟ ਭਈ ਜਗ ਮਾਇ।","roman":"Jab bahu tah tapsaa karee pragat bhaee jag maai |","meaning_en":"When she had done much austerity there, the Mother of the world appeared.","page":2211,"meaning_status":"draft"},{"gurmukhi":"ਬਰੰਬ੍ਰ�ਹ ਤਾ ਸੌ ਕਹਿਯੋ ਜੋ ਤੁਹਿ ਸੁਤਾ ਸੁਹਾਇ। ੯੬।","roman":"Baranbr(?)ha taa sau kahiyo jo tuhi sutaa suhaai | 96 |","meaning_en":"[unclear] said to her: 'Ask what pleases you, daughter.'","page":2211,"flags":[{"code":"0xad","reason":"unresolved: draws an empty box in the PDF itself: the source font lacks this glyph"}],"meaning_status":"draft","note":"the word ਬਰੰਬ੍ਰ?ਹ has a corrupt/unreadable character in the printed text; read perhaps as 'the Goddess/Brahm'; unclear."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2213,"meaning_status":"draft"},{"type":"verse","number":[97],"number_text":"੯੭।","page":2213,"lines":[{"gurmukhi":"ਮੈਯਾ ਇਹੈ ਦਾਨੁ ਮੁਹਿ ਦੀਜੈ। ਰਛਾ ਆਪੁ ਹਮਾਰੀ ਕੀਜੈ।","roman":"Maiyaa ihai daanu muhi deejai | rachhaa aapu hamaaree keejai |","meaning_en":"'Mother, give me this gift: protect me yourself.","page":2213,"meaning_status":"draft"},{"gurmukhi":"ਛਤ੍ਰਾਨੀ ਗ੍ਰਿਹਿ ਤੁਰਕ ਨ ਜਾਇ। ਮੁਹਿ ਬਰ ਦੇਹੁ ਇਹੇ ਜਗ ਮਾਇ। ੯੭।","roman":"Chhatraanee grihi turak na jaai | muhi bar dehu ihe jag maai | 97 |","meaning_en":"Let no Kshatriya woman go to a Turk's house; give me this boon, Mother of the world.'","page":2213,"meaning_status":"draft"}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":2213,"lines":[{"gurmukhi":"ਚਰਨਨ ਰਹੈ ਤਿਹਾਰੈ ਚਿਤਾ। ਗ੍ਰਿਹ ਮਹਿ ਹੋਇ ਅਨਗਨਤ ਬਿਤਾ।","roman":"Charnan rahai tihaarai chitaa | grih mahi hoi anagnat bitaa |","meaning_en":"'Let my mind stay at your feet; let there be countless wealth in the house.","page":2213,"meaning_status":"draft"},{"gurmukhi":"ਸਤ੍ਰੁ ਨ ਜੀਤਿ ਹਮੈ ਕੋਈ ਜਾਇ। ਤੁਮ ਮਹਿ ਰਹੈ ਮੋਰ ਮਨ ਮਾਇ। ੯੮।","roman":"Satru na jeeti hamai koee jaai | tum mahi rahai mor man maai | 98 |","meaning_en":"Let no enemy conquer us; let my mind stay in you, Mother.'","page":2213,"meaning_status":"draft"}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":2213,"lines":[{"gurmukhi":"ਜਗ ਮਾਤੈ ਐਸੇ ਬਰੁ ਦੀਯੋ। ਤਿਨ ਕਹ ਰਾਜ ਅਸਾਮ ਕੋ ਕੀਯੋ।","roman":"Jag maatai aise baru deeyo | tin kah raaj asaam ko keeyo |","meaning_en":"The Mother of the world gave such a boon, and made them kings of Assam.","page":2213,"meaning_status":"draft"},{"gurmukhi":"ਅਬ ਲਗਿ ਰਾਜ ਤਹਾ ਤੈ ਕਰੈ। ਦਿਲੀਪਤਿ ਕੀ ਕਾਨਿ ਨ ਧਰੈ। ੯੯।","roman":"Ab lagi raaj tahaa tai karai | dileepti kee kaani na dharai | 99 |","meaning_en":"Even now they rule there, and pay no heed to the lord of Delhi.","page":2213,"meaning_status":"draft"}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":2213,"lines":[{"gurmukhi":"ਜਿਨ ਕਹ ਰਾਜ ਭਵਾਨੀ ਦੀਯੋ। ਤਿਨ ਤੇ ਛੀਨਿ ਨ ਕਿਨਹੂੰ ਲੀਯੋ।","roman":"Jin kah raaj bhavaanee deeyo | tin te chheeni na kinhoon leeyo |","meaning_en":"Those to whom Bhavani gave the kingdom, no one has taken it from them.","page":2213,"meaning_status":"draft"},{"gurmukhi":"ਅਬ ਲੌ ਕਰਤ ਤਹਾ ਕੋ ਰਾਜਾ। ਰਿਧਿ ਸਿਧਿ ਸਭ ਹੀ ਘਰ ਸਾਜਾ। ੧੦੦।","roman":"Ab lau karat tahaa ko raajaa | ridhi sidhi sabh hee ghar saajaa | 100 |","meaning_en":"Even now their king rules there, with all wealth and powers in his house.","page":2213,"meaning_status":"draft"}]},{"type":"verse","number":[101,1],"number_text":"੧੦੧। ੧।","page":2213,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਦਿਲਿਸ ਸੌ ਪਿਤਾ ਜੁਝਾਯੋ। ਪੁਨਿ ਦੇਬੀ ਤੇ ਅਸ ਬਰ ਪਾਯੋ।","roman":"Pratham dilis sau pitaa jujhaayo | puni debee te as bar paayo |","meaning_en":"First she had her father fight the lord of Delhi; then she received such a boon from the Goddess.","page":2213,"meaning_status":"draft"},{"gurmukhi":"ਅੰਗ ਦੇਸ ਕੇ ਭਏ ਨ੍ਰਿਪਾਰਾ। ਇਹ ਛਲ ਅਬਲਾ ਧਰਮ ਉਬਾਰਾ। ੧੦੧। ੧।","roman":"Ang des ke bhae nripaaraa | ih chhal ablaa dharam ubaaraa | 101 | 1 |","meaning_en":"They became kings of the Anga country; by this trick the woman saved her dharma.","page":2213,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਦੋ ਸੌ ਸਤਾਨਵੋ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade do sau sataanvo charitr samaaptam","meaning_en":"Thus ends the 297th charitra of the Charitropakhyan, of the wiles of women, in the dialogue of the minister and the king; complete.","page":2213,"meaning_status":"draft"},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੨੯੭। ੫੭੫੦। ਅਫਜੂੰ।","roman":"Satu subham satu | 297 | 5750 | aphjoon |","meaning_en":"True, auspicious, true. 297. 5750. It continues.","page":2213,"meaning_status":"draft"}],"page":2213,"number":[297,5750]}});
